package com.example

import com.example.ExamQuestionHelper.QSpec

internal object HistoryLiveExamWetZoneKingdomsBank {
  private const val T = "නිරිතදිග රාජධානි හා යාපනය රාජධානිය"

  private fun q(
    t: String,
    s: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    e: String
  ) = QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun wetZoneKingdomsQuestions(): List<QSpec> = listOf(
    q(T, "පොළොන්නරුවේ බිඳවැටීමෙන් පසු නිරිතදිග ලංකාවේ බිහිවූ ප්‍රථම රාජධානිය කුමක්ද?", "දඹදෙණි රාජධානිය", "යාපහුව", "කුරුණෑගල", "ගම්පොළ", "කාලිංග මාඝගේ විනාශයෙන් පසු තුන්වන විජයබාහු රජු දඹදෙණිය සිය අගනුවර කරගත්තේය."),
    q(T, "දඹදෙණි රාජධානිය ආරම්භ කළ ප්‍රථම පාලකයා කවුද?", "තුන්වන විජයබාහු රජු", "දෙවන පරාක්‍රමබාහු රජු", "හතරවන විජයබාහු රජු", "පළමුවන බුවනෙකබාහු රජු", "ක්‍රි.ව. 1220 දී පමණ තුන්වන විජයබාහු රජු දඹදෙණියේ බලය පිහිටුවීය."),
    q(T, "තුන්වන විජයබාහු රජු මාඝගේ තර්ජනවලින් බේරා ගැනීම සඳහා දන්ත ධාතුව සහ පාත්‍රා ධාතුව සඟවා තැබූ ආරක්ෂිත පර්වතය කුමක්ද?", "බෙලිගල පව්ව", "සීගිරිය", "යාපහුව", "දඹුල්ල", "කොත්මලේ සඟවා තිබූ දළදා වහන්සේ වැඩම කරවා බෙලිගල පර්වත මුදුනේ මාලිගයක් තනා ආරක්ෂා කළේය."),
    q(T, "දඹදෙණියේ විජයසුන්දරාරාමය කරවා සංඝරත්නය රැස්කර ශාසනික පුනර්ජීවනයක් ඇති කළ රජු කවුද?", "තුන්වන විජයබාහු රජු", "දෙවන බුවනෙකබාහු රජු", "පස්වන පරාක්‍රමබාහු රජු", "වීරබාහු රජු", "විජයසුන්දරාරාමය තනා දළදා පෙරහැර පැවැත්වීමට හා උපසම්පදාව ලබා දීමට කටයුතු කළේය."),
    q(T, "දඹදෙණි යුගයේ රජ පැමිණි ශ්‍රේෂ්ඨතම පාලකයා මෙන්ම 'කලිකාල සාහිත්‍ය සර්වඥ පණ්ඩිත' නාමයෙන් පිදුම් ලැබූ රජු කවුද?", "දෙවන පරාක්‍රමබාහු රජු", "තුන්වන විජයබාහු රජු", "හතරවන පරාක්‍රමබාහු රජු", "හයවන පරාක්‍රමබාහු රජු", "මහා විද්වතෙකු වූ දෙවන පරාක්‍රමබාහු රජු සාහිත්‍යයට හා රට එක්සේසත් කිරීමට මහා මෙහෙවරක් කළේය."),
    q(T, "දෙවන පරාක්‍රමබාහු රජු විසින් රචනා කරන ලද විශිෂ්ටතම සිංහල මහා කාව්‍යය කුමක්ද?", "කව්සිළුමිණ (කුසදාවත)", "මුවදෙව්දාවත", "සසදාවත", "කාව්‍යශേഖරය", "කුස ජාතකය ඇසුරෙන් රචිත කව්සිළුමිණ සිංහල පද්‍ය සාහිත්‍යයේ අග්‍රගණ්‍ය කෘතියකි."),
    q(T, "දෙවන පරාක්‍රමබාහු රජු විසින් විශුද්ධිමාර්ගයට ලියන ලද අගනා සිංහල ටීකාව කුමක්ද?", "විසුද්ධිමග්ග සන්නය", "ධර්මප්‍රදීපිකාව", "අමාවතුර", "බුත්සරණ", "පාලි විශුද්ධිමාර්ගය ගැඹුරින් විග්‍රහ කරමින් විසුද්ධිමග්ග සන්නය රචනා කළේය."),
    q(T, "දඹදෙණි යුගයේ භික්ෂු විනය ආරක්ෂා කිරීම සඳහා දෙවන පරාක්‍රමබාහු රජු විසින් පිහිටුවූ විනය නීති සංග්‍රහය කුමක්ද?", "දඹදෙණි කතිකාවත", "පොළොන්නරු කතිකාවත", "කීර්ති ශ්‍රී කතිකාවත", "අනුරාධපුර කතිකාවත", "ශාසනයේ පාරිශුද්ධත්වය රැකීමට දිඹුලාගල ආරණ්‍යවාසී මේධංකර හිමියන්ගේ මුල්ත්වයෙන් දඹදෙණි කතිකාවත සම්පාදනය විය."),
    q(T, "ක්‍රි.ව. 1247 දී ජාවා (තාම්බ්‍රලිංග) දේශයේ සිට ලංකාව ආක්‍රමණය කළ විදේශීය ආක්‍රමණිකයා කවුද?", "චන්ද්‍රභානු", "කාලිංග මාඝ", "ආර්යචක්‍රවර්තී", "චෙං හෝ", "විෂ දුනු ඊතල රැගත් ජාවක හමුදාවක් සමඟ පැමිණි චන්ද්‍රභානු දළදා වහන්සේ ඉල්ලා ආක්‍රමණය කළේය."),
    q(T, "දෙවන පරාක්‍රමබාහු රජුගේ කාලයේ චන්ද්‍රභානුගේ පළමු ආක්‍රමණය සාර්ථකව මැඩපැවැත්වූ සිංහල සෙන්පතියා කවුද?", "වීරබාහු සෙන්පතියා", "දේවපතිරාජ ඇමති", "බුදල්නා", "මිගාර", "පරාක්‍රමබාහු රජුගේ බෑණනුවන් වූ වීරබාහු කුමරු ජාවක හමුදාව සම්පූර්ණයෙන්ම පරාජය කළේය."),
    q(T, "දඹදෙණි යුගයේ දෙවන පරාක්‍රමබාහු රජුගේ ප්‍රධාන අග්‍රාමාත්‍යවරයා ලෙස විශිෂ්ට සේවයක් කළ පුද්ගලයා කවුද?", "දේවපතිරාජ අමාත්‍යවරයා", "අලගක්කෝනාර", "සෙනෙවිරත්", "ඉසිගිරිය", "දේවපතිරාජ ඇමති මාර්ග, පාලම්, ආරාම හා පොල් වතු වගා කරමින් අතිවිශාල සංවර්ධනයක් රට තුළ සිදුකළේය."),
    q(T, "දේවපතිරාජ අමාත්‍යවරයා විසින් අත්තනගල්ලේ සිට බෙන්තොට දක්වා යොදුන් තුනක දිගින් යුතුව කළ වගාව කුමක්ද?", "මහා පොල් උයන", "තේ වගාව", "කුරුඳු වගාව", "කෝපි වගාව", "ආහාර සුරක්ෂිතතාව හා ආර්ථික ශක්තිය සඳහා සැතපුම් ගණනාවක් දිග පොල් උයනක් වගා කරවන ලදී."),
    q(T, "දෙවුන්දර සහ ශ්‍රී පාදස්ථානයට යන බැතිමතුන්ගේ පහසුව සඳහා පාලම්, අම්බලම් හා මාර්ග ඉදිකළ දඹදෙණි ඇමතිවරයා කවුද?", "දේවපතිරාජ ඇමති", "අලගක්කෝනාර ඇමති", "බුදල්නා ඇමති", "වික්‍රමසිංහ ඇමති", "දෙවුන්දර උපුල්වන් දෙවොල පිළිසකර කර කළුගඟ හරහා දැව පාලම් තනා වන්දනාකරුවන්ට පහසුකම් සැලසීය."),
    q(T, "දෙවන පරාක්‍රමබාහු රජුගේ ඇවෑමෙන් 'බෝසත් විජයබාහු' නමින් රජ පැමිණි රජු කවුද?", "හතරවන විජයබාහු රජු", "තුන්වන පරාක්‍රමබාහු රජු", "පළමුවන බුවනෙකබාහු රජු", "හයවන විජයබාහු රජු", "ධාර්මික දිවිපෙවෙත නිසා බෝසත් විජයබාහු නමින් හැඳින්වුණු මොහු පොළොන්නරුව නගරය ප්‍රතිසංස්කරණය කළේය."),
    q(T, "හතරවන විජයබාහු (බෝසත් විජයබාහු) රජු මරා දමා රාජ්‍ය බලය පැහැර ගැනීමට උත්සාහ කළ ද්‍රෝහී සෙන්පතියා කවුද?", "මිත්ත සෙන්පතියා", "ආර්යචක්‍රවර්තී", "චන්ද්‍රභානු", "කුලසේකර", "මිත්ත සෙන්පතියා කුමන්ත්‍රණයකින් රජු මැරවූ නමුත් බුවනෙකබාහු කුමරුගේ හමුදා ඔහුව ඝාතනය කළහ."),
    q(T, "මිත්ත සෙන්පතියාගේ කැරැල්ල මර්දනය කරමින් පළමුවන බුවනෙකබාහු රජු ආරක්ෂා කළ විදේශීය කුලී හමුදා නායකයා කවුද?", "ඨකුරක සෙන්පතියා", "ලංකාපුර", "චන්ද්‍රභානු", "මාඝ", "ආර්ය රාජපුත්‍ර කුලී හමුදාවේ නායකයා වූ ඨකුරක මිත්ත සෙන්පතියා මරා බුවනෙකබාහු කුමරු බේරා ගත්තේය."),
    q(T, "දඹදෙණියෙන් පසු ස්වාභාවික ආරක්ෂිත පර්වතයක් මත 'යාපහුව' අගනුවර කරගත් රජු කවුද?", "පළමුවන බුවනෙකබාහු රජු", "හතරවන පරාක්‍රමබාහු රජු", "තුන්වන විජයබාහු රජු", "දෙවන බුවනෙකබාහු රජු", "ක්‍රි.ව. 1272 දී පළමුවන බුවනෙකබාහු රජු සුභ පබ්බත හෙවත් යාපහුව තම රාජධානිය කරගත්තේය."),
    q(T, "යාපහුව රාජධානියේ නටබුන් අතර අදටත් දෙස් විදෙස් සංචාරකයන් මවිත කරවන ප්‍රධාන නිර්මාණය කුමක්ද?", "පියගැට පෙළ සහ මනරම් වාහල්කඩ සහිත දළදා මාලිගය", "ගඩොල් ස්තූපය", "පොකුණු පද්ධතිය පමණක්", "ලෙන් ආරාමය", "චීන හා දකුණු ඉන්දියානු කලා ආභාසය කැටි වූ ගල් පියගැට පෙළ හා සිංහ කැටයම් විශිෂ්ටය."),
    q(T, "යාපහුව පියගැට පෙළ දෙපස ඇති ගල් කැටයම් අතර අද්විතීය මුහුණුවරක් ගන්නා සත්ත්ව රූපය කුමක්ද?", "යාපහු සිංහයා (චීන කලා ආභාසය සහිත)", "අලියා", "ගවයා", "මකරා", "චීන බෞද්ධ කලා ලක්ෂණ සහිත තියුණු නෙත් හා කේශර සහිත යාපහු සිංහ රූපය ප්‍රකටය."),
    q(T, "ඊජිප්තුවේ කයිරෝ නුවර සුල්තාන්වරයා වෙත වෙළෙඳ දූත පිරිසක් යැවූ ශ්‍රී ලාංකික රජු කවුද?", "පළමුවන බුවනෙකබාහු රජු (යාපහුව)", "මහා පරාක්‍රමබාහු රජු", "දෙවන පරාක්‍රමබාහු රජු", "හයවන පරාක්‍රමබාහු රජු", "ක්‍රි.ව. 1283 දී ඊජිප්තු සුල්තාන් අල් මුස්තන්සීර් වෙත ඇතුන්, මැණික් හා කුරුඳු වෙළෙඳාම සඳහා දූත පිරිසක් යැවීය."),
    q(T, "යාපහුව රාජධානිය බිඳවැටීමට බලපෑ ප්‍රධානතම විදේශීය ආක්‍රමණය කුමක්ද?", "පාණ්ඩ්‍ය සෙන්පති ආර්යචක්‍රවර්තීගේ ආක්‍රමණය", "කාලිංග මාඝගේ ආක්‍රමණය", "චෝල ආක්‍රමණය", "පෘතුගීසි ආක්‍රමණය", "පාණ්ඩ්‍ය රජ කුලසේකරගේ නියෝගයෙන් ආර්යචක්‍රවර්තී යාපහුව ආක්‍රමණය කර දන්ත ධාතුව මදුරෙයි නුවරට රැගෙන ගියේය."),
    q(T, "පාණ්ඩ්‍ය දේශයට රැගෙන ගිය දන්ත ධාතූන් වහන්සේ රාජ්‍ය තාන්ත්‍රික සාකච්ඡා මගින් යළි ලංකාවට වැඩම කරවූ රජු කවුද?", "තුන්වන පරාක්‍රමබාහු රජු", "පළමුවන බුවනෙකබාහු රජු", "හතරවන පරාක්‍රමබාහු රජු", "දෙවන විජයබාහු රජු", "තුන්වන පරාක්‍රමබාහු කුලසේකර රජු හමුවී මිත්‍රශීලීව සාකච්ඡා කර දළදා වහන්සේ ආපසු ගෙනැවිත් පොළොන්නරුවේ තැන්පත් කළේය."),
    q(T, "යාපහුවෙන් පසු 'හස්තිශෛලපුර' හෙවත් කුරුණෑගල සිය රාජධානිය කරගත් රජු කවුද?", "දෙවන බුවනෙකබාහු රජු", "පළමුවන බුවනෙකබාහු රජු", "පස්වන පරාක්‍රමබාහු රජු", "තුන්වන විජයබාහු රජු", "ඇතුගල පාමුල කුරුණෑගල නගරය සිය රාජධානිය ලෙස දෙවන බුවනෙකබාහු විසින් තෝරා ගන්නා ලදී."),
    q(T, "කුරුණෑගල යුගයේ රජ පැමිණි ශ්‍රේෂ්ඨතම ධාර්මික හා සාහිත්‍යධර පාලකයා කවුද?", "හතරවන පරාක්‍රමබාහු රජු (පණ්ඩිත පරාක්‍රමබාහු)", "දෙවන බුවනෙකබාහු රජු", "තුන්වන බුවනෙකබාහු රජු", "පස්වන විජයබාහු රජු", "හතරවන පරාක්‍රමබාහු රජු දළදා සිරිත හා ජාතක පොත ලියවමින් අමිල ශාස්ත්‍රීය මෙහෙවරක් ඉටු කළේය."),
    q(T, "පාලි ජාතකට්ඨකතාව සිංහලට පරිවර්තනය කර 'පන්සිය පනස් ජාතක පොත' සම්පාදනය කරවූයේ කුමන රජු විසින්ද?", "හතරවන පරාක්‍රමබාහු රජු", "දෙවන පරාක්‍රමබාහු රජු", "තුන්වන විජයබාහු රජු", "හයවන පරාක්‍රමබාහු රජු", "ජාතක කතා 550ක් සිංහල ගැමි බසට පෙරළා සිංහල බෞද්ධ සාහිත්‍යයේ මහා නිධානයක් බිහි කළේය."),
    q(T, "දළදා වහන්සේ උදෙසා කළ යුතු තේවාවන්, පුද සිරිත් හා පෙරහැර චාරිත්‍ර නීතිගත කරමින් ලියැවුණු ග්‍රන්ථය කුමක්ද?", "දළදා සිරිත", "දන්තධාතුවංශය", "චූලවංශය", "රාජාවලිය", "හතරවන පරාක්‍රමබාහු රජුගේ නියමයෙන් දළදා වහන්සේ වන්දනාමාන කරන චාරිත්‍ර පද්ධතිය දළදා සිරිතෙහි ඇතුළත් විය."),
    q(T, "කුරුණෑගල යුගයේ බිහිවූ අලංකාර ව්‍යාකරණ ග්‍රන්ථයක් වූ 'සුබෝධාලංකාර සන්නය' රචනා කළේ කවුද?", "හතරවන පරාක්‍රමබාහු රජු", "විදුරුමහපාමුල හිමි", "තොටගමුවේ ශ්‍රී රාහුල හිමි", "වීදාගම මෛත්‍රිය හිමි", "හතරවන පරාක්‍රමබාහු රජු විසින් පාලි කාව්‍ය අලංකාර විග්‍රහ කරමින් මෙය සම්පාදනය කරන ලදී."),
    q(T, "කුරුණෑගල රාජධානියෙන් පසුව මහවැලි ගං ඉවුරේ පිහිටි 'ගඟසිරිපුර' හෙවත් ගම්පොළ අගනුවර කරගත් රජු කවුද?", "හතරවන බුවනෙකබාහු රජු", "තුන්වන වික්‍රමබාහු රජු", "පස්වන පරාක්‍රමබාහු රජු", "හයවන බුවනෙකබාහු රජු", "ක්‍රි.ව. 1341 දී හතරවන බුවනෙකබාහු රජු ගම්පොළ තම රාජධානිය කරගත්තේය."),
    q(T, "ගම්පොළ යුගයේදී මුළුමනින්ම කළුගලින් නිමවන ලද දකුණු ඉන්දියානු විජයනගර් කලා ආභාසය සහිත විහාරය කුමක්ද?", "ගඩලාදෙණිය විහාරය", "ලංකාතිලකය", "ඇම්බැක්ක", "දෙගල්දොරුව", "ගනේශ්වරාචාරී නම් දකුණු ඉන්දියානු ගෘහ නිර්මාණ ශිල්පියාගේ මූලිකත්වයෙන් ගඩලාදෙණිය නිමවිණි."),
    q(T, "ගම්පොළ යුගයේදී ඉදිකළ 'ලංකාතිලක විහාරය' නිර්මාණයේ ඇති සුවිශේෂත්වය කුමක්ද?", "මධ්‍යයේ බුද්ධ ප්‍රතිමා ගෘහයක් සහ සිව් කොණේ දේව ප්‍රතිමා සහිත සිංහල-ද්‍රවිඩ සම්මිශ්‍රණ වාස්තු විද්‍යාවක් වීම", "එය ලීයෙන් පමණක් සාදා තිබීම", "මුළුමනින්ම ලෙන් විහාරයක් වීම", "වීදුරු කුළුණු තිබීම", "සෙනාධිලංකාර ඇමතිවරයාගේ මූලිකත්වයෙන් ගඩොලින් හා කළුගලින් මහල් හතරකින් යුතුව ලංකාතිලකය ඉදිකෙරිණි."),
    q(T, "ගම්පොළ යුගයේ දැව කැටයම් කලාවේ කූටප්‍රාප්තිය සනිටුහන් කරන ඓතිහාසික සිද්ධස්ථානය කුමක්ද?", "ඇම්බැක්කේ දේවාලය", "ගඩලාදෙණිය", "විජයසුන්දරාරාමය", "දඹදෙණිය", "තුන්වන වික්‍රමබාහු රජුගේ මඟපෙන්වීමෙන් කතරගම දෙවියන් උදෙසා ඇම්බැක්කේ දිග්ගෙයි දැව කැටයම් නිර්මාණය විය."),
    q(T, "ඇම්බැක්කේ දේවාලයේ දැව කුළුණු මත කැටයම් කර ඇති සුප්‍රකට මෝස්තරයක් වන්නේ කුමක්ද?", "ලණු ගැටය, කිඳුරු රූප, මල්ලවපොර හා හංස පූට්ටුව", "මෝටර් රථ රූප", "විදේශීය තුවක්කු", "කඩදාසි මල්", "සම්ප්‍රදායික සිංහල කැටයම් මෝස්තර 128ක් පමණ ඇම්බැක්කේ දැව කුළුණුවල දැකගත හැකිය."),
    q(T, "ගම්පොළ යුගයේදී ආර්යචක්‍රවර්තීගේ ආක්‍රමණ මැඩපැවැත්වීම සඳහා 'ජයවර්ධනපුර කෝට්ටේ' බලකොටුව ඉදිකළ අමාත්‍යවරයා කවුද?", "නිශ්ශංක අලගක්කෝනාර (දසවන අලකේශ්වර)", "දේවපතිරාජ", "බුදල්නා", "මිගාර", "දියවන්නා ඔය හා වගුරු බිම්වලින් වටවූ ස්වාභාවික ආරක්ෂිත භූමියක කබොක් ගල් ප්‍රාකාර බැඳ කෝට්ටේ බලකොටුව හැදුවේය."),
    q(T, "කෝට්ටේ බලකොටුව නිර්මාණය කිරීමේදී ආරක්ෂාව සඳහා යොදාගත් ප්‍රධාන පාරිසරික බාධකය කුමක්ද?", "දියවන්නා ඔය ඇතුළු ගැඹුරු වගුරු බිම් සහ දිය අගල්", "හිම කඳු", "කාන්තාර", "විශාල ගිනි කඳු", "දිය අගල් හා ගොඩ අගල් කැපීමෙන් හා කබොක් බැමි නැංවීමෙන් අපරාජිත බලකොටුවක් ලෙස කෝට්ටේ සැලසුම් කළේය."),
    q(T, "යාපනයේ ආර්යචක්‍රවර්තී බස්නාහිර පළාතේ වෙළෙඳපොළවලින් බදු අය කිරීම සඳහා යොදවා තිබූ බදු පොත් හැඳින්වූයේ කුමන නමින්ද?", "වරිපොත්", "කඩඉම් පොත්", "ලේකම් මිටි", "තුඩපත්", "කොළඹ, පානදුර ආදී ප්‍රදේශවලින් බදු එකතු කිරීමට ආර්යචක්‍රවර්තී නිලධාරීන් යොදවා තිබුණි."),
    q(T, "අලගක්කෝනාර අමාත්‍යවරයා ආර්යචක්‍රවර්තීගේ බදු අයකැමියන්ට කළ ප්‍රතිචාරය කුමක්ද?", "බදු දීම ප්‍රතික්ෂේප කර ඔවුන් අල්ලා එල්ලා දැමීම", "ඉල්ලා සිටි සියලු බදු ගෙවීම", "රට හැර දමා පලා යාම", "ආර්යචක්‍රවර්තීට යටත් වීම", "මෙම නිර්භීත ක්‍රියාව නිසා ආර්යචක්‍රවර්තී ගොඩබිමින් හා මුහුදින් කෝට්ටේ ආක්‍රමණය කිරීමට සේනා එව්වේය."),
    q(T, "ආර්යචක්‍රවර්තීගේ ගොඩබිම් හා මුහුදු හමුදා එකවර පරාජය කළ ඓතිහාසික සටන් පැවතියේ කොහේද?", "පානදුර තොටුපළ හා කොළඹ දෙමටගොඩ ප්‍රදේශවලදී", "කතරගමදී", "අනුරාධපුරයේදී", "මන්නාරමේදී", "අලගක්කෝනාර ඇමතිවරයාගේ යුද උපක්‍රම හමුවේ ආර්යචක්‍රවර්තීගේ හමුදා දරුණු පරාජයක් ලැබීය."),
    q(T, "ගම්පොළ යුගයේදී රචනා වූ සිංහල සන්දේශ කාව්‍ය දෙක මොනවාද?", "තිසර සන්දේශය සහ මයුර සන්දේශය", "සැළලිහිණි හා ගිරා සන්දේශය", "කෝකිල හා පරවි සන්දේශය", "හංස හා නීලකොබෝ සන්දේශය", "දෙවන පරාක්‍රමබාහු සහ තුන්වන වික්‍රමබාහු සමයන්හි මෙම පැරණි සන්දේශ කාව්‍ය රචනා විය."),
    q(T, "දැදිගම කොටවෙහෙර (සූතිඝර චෛත්‍යය) කැණීමේදී හමුවූ ලෝක ප්‍රසිද්ධ ලෝකඩ නිර්මාණය කුමක්ද?", "දැදිගම ඇත් පහන (Elephant Lamp)", "නටරාජා පිළිමය", "සමාධි පිළිමය", "තාරා දේවී පිළිමය", "ද්‍රවස්ථිති මූලධර්මය මත තෙල් පිරෙන අන්දමට නිමවා ඇති දැදිගම ඇත් පහන විස්මිත ඉංජිනේරු නිර්මාණයකි."),
    q(T, "දැදිගම කොටවෙහෙර ඉදිකරන ලද්දේ කුමන ඓතිහාසික සිදුවීමක් සිහිපත් කිරීම සඳහාද?", "මහා පරාක්‍රමබාහු රජු උපන් ස්ථානය (සූතිඝරය) සැමරීමට", "යුද්ධයක් දිනීම සැමරීමට", "දළදා වහන්සේ වැඩමවීම සැමරීමට", "සාගතයක් අවසන් වීම සැමරීමට", "දක්ෂිණදේශයේ පාලකයා වූ මානාභරණ රජුගේ පුත් පරාක්‍රමබාහු කුමරු උපන් ස්ථානයේ මෙම ස්තූපය ඉදිකළේය."),
    q(T, "ක්‍රි.ව. 1411 දී ශ්‍රී ලංකාවට පැමිණ වීර අලකේශ්වර රජු සිරභාරයට ගෙන චීනයට රැගෙන ගිය චීන නාවික සෙන්පතියා කවුද?", "චෙං හෝ සෙන්පතියා (Zheng He)", "පාහියන් හිමි", "හියුං සාං හිමි", "කුබ්ලායි ඛාන්", "විශාල නෞකා බලඇණියක් සමඟ පැමිණි චෙං හෝ රජු පැහැරගෙන ගොස් මිං අධිරාජයා හමුවට පැමිණවීය."),
    q(T, "චෙං හෝ සෙන්පතියා ලංකාවට පැමිණි ගමන සිහිපත් කරමින් ගාල්ලේ පිහිටවූ ත්‍රෛභාෂික සෙල්ලිපියේ අඩංගු භාෂා තුන මොනවාද?", "චීන, පර්සියානු සහ දෙමළ භාෂාව", "සිංහල, පාලි සහ සංස්කෘත", "ඉංග්‍රීසි, ලන්දේසි හා පෘතුගීසි", "හින්දි, උර්දු හා අරාබි", "ගාලු ත්‍රෛභාෂික පුවරු ලිපිය වර්තමානයේ කොළඹ ජාතික කෞතුකාගාරයේ තැන්පත් කර ඇත."),
    q(T, "යාපනය අර්ධද්වීපය කේන්ද්‍ර කරගත් 'යාපනය රාජධානිය' බිහිවීමට බලපෑ ආසන්න සාධකය කුමක්ද?", "කාලිංග මාඝගේ ආක්‍රමණය හා දකුණු ඉන්දියානු පාණ්ඩ්‍ය අධිරාජ්‍යයේ ව්‍යාප්තිය", "පෘතුගීසීන් පැමිණීම", "අනුරාධපුරයේ සාගතයක් හටගැනීම", "බ්‍රිතාන්‍ය ආක්‍රමණය", "13 වන සියවසේදී ආර්යචක්‍රවර්තී පෙළපත විසින් නල්ලූර් අගනුවර කරගනිමින් යාපනය රාජධානිය පිහිටුවීය."),
    q(T, "යාපනය රාජධානියේ අගනුවර වූ ප්‍රධාන ඓතිහාසික නගරය කුමක්ද?", "නල්ලූර්", "වඩුක්කොඩෙයි", "චාවකච්චේරි", "පේදුරුතුඩුව", "නල්ලූර් නගරයේ කන්දසාමි කෝවිල සහ රාජකීය මාළිගා පිහිටා තිබුණි."),
    q(T, "යාපනය රාජධානියේ ආර්ථික ශක්තියට ප්‍රධාන වශයෙන්ම දායක වූ ස්වාභාවික සම්පත කුමක්ද?", "මන්නාරම් බොක්කේ මුතු කිමිදීම සහ ලුණු ලේවායන්", "තේ වගාව", "මැණික් පතල්", "යකඩ කර්මාන්තය", "මුතු, හක්ගෙඩි, ලුණු සහ අලි ඇතුන් විදේශ වෙළෙඳුන්ට විකිණීමෙන් විශාල ආදායමක් ලැබිණි."),
    q(T, "යාපනය පාලනය කළ ආර්යචක්‍රවර්තී රජවරුන් භාවිත කළ රාජකීය සංකේතය කුමක්ද?", "සේතු කාසිය (නන්දි හෙවත් ගව රූපය සහිත)", "සිංහ රූපය", "හංස රූපය", "ඇත් රූපය", "සේතු ලාංඡනය සහිත කාසි හා රාජකීය ලියකියවිලි ඔවුන් භාවිත කළහ."),
    q(T, "නිරිතදිග රාජධානි යුගයේදී ශ්‍රී ලංකාවේ කෘෂිකාර්මික ජීවිතයේ සිදුවූ ප්‍රධාන වෙනස කුමක්ද?", "මහා වැව් වෙනුවට තෙත් කලාපයේ වැසි ජලයෙන් යැපෙන කුඹුරු හා ගෙවතු වගාව ප්‍රධාන වීම", "කෘෂිකර්මය මුළුමනින්ම අත්හැරීම", "තිරිඟු වගාව පමණක් කිරීම", "සාගත පමණක් ඇතිවීම", "කඳුකර බෑවුම්වල ලියැදි තනා කුඹුරු අස්වැද්දීම හා පොල්, පුවක්, කුළුබඩු වගාව දියුණු විය."),
    q(T, "නිරිතදිග රාජධානි කාලයේදී රටේ ආරක්ෂාවට වඩාත්ම උපකාරී වූ භූගෝලීය සාධකය කුමක්ද?", "ගිරිදුර්ග, වනදුර්ග සහ ජලදුර්ග (කඳු, ඝන වනාන්තර හා ගංගා)", "විශාල තැනිතලා", "කාන්තාර", "විශාල මුහුදු වෙරළ", "සතුරන්ට පහසුවෙන් ළඟාවිය නොහැකි ලෙස උස් ගල් පර්වත හා වනාන්තර උපයෝගී කරගෙන බලකොටු තැනීය."),
    q(T, "දඹදෙණි යුගයේ බිහිවූ අගනා ධර්ම කෘතියක් වන 'සද්ධර්මරත්නාවලිය' රචනා කළ හිමිනම කවුද?", "ධර්මසේන හිමි", "බුද්ධපුත්‍ර හිමි", "විදුරුමහපාමුල හිමි", "ශ්‍රී රාහුල හිමි", "පාලි ධම්මපදට්ඨකතාව ඇසුරෙන් ගැමි බස මුසු කරමින් සද්ධර්මරත්නාවලිය රචනා විය."),
    q(T, "දඹදෙණි යුගයේදී බුද්ධපුත්‍ර හිමියන් විසින් රචිත 'පූජාවලිය' ග්‍රන්ථය පූජා කරන ලද්දේ කා හටද?", "දෙවන පරාක්‍රමබාහු රජුට සහ මහා සංඝරත්නයට", "විජයබාහු රජුට", "අලගක්කෝනාරට", "චන්ද්‍රභානුට", "බුදුරජාණන් වහන්සේගේ අරහං බුදුගුණය වර්ණනා කරමින් රචිත පූජාවලිය දඹදෙණි සාහිත්‍යයේ මුදුන් මල්කඩකි."),
    q(T, "දඹදෙණි යුගයේ රචිත පැරණිතම සිංහල ව්‍යාකරණ ග්‍රන්ථය වන්නේ කුමක්ද?", "සිදත් සඟරාව", "බාලාවතාරය", "මොග්ගල්ලාන ව්‍යාකරණය", "පදසාධනය", "වේදේහ හිමියන්ගේ උපදෙස් මත පද්‍ය හා ගද්‍ය ව්‍යාකරණ නීති දක්වමින් සිදත් සඟරාව ලියැවිණි."),
    q(T, "දඹදෙණි යුගයේ වේදේහ හිමියන් විසින් පාලි භාෂාවෙන් රචිත කෘති දෙක මොනවාද?", "සමන්තකූට වණ්ණනාව සහ රසවාහිනිය", "මහාවංශය හා දීපවංශය", "චූලවංශය", "ථූපවංශය", "ශ්‍රී පාදස්ථානය වර්ණනා කරමින් සමන්තකූට වණ්ණනාව පාලි පද්‍යයෙන් රචනා කරන ලදී."),
    q(T, "යාපහුව බලකොටුවේ ආරක්ෂාව සඳහා පර්වතය පාමුල ඉදිකර තිබූ ආරක්ෂක විධිවිධානය කුමක්ද?", "ද්විත්ව දිය අගල් සහ දැවැන්ත මැටි හා ගල් බැමි", "යකඩ දැල්", "වීදුරු බිත්ති", "ගිනි වළවල්", "පිටත ප්‍රාකාරය හා ඇතුළු ප්‍රාකාරය අතර දිය අගල් කපා ආරක්‍ෂාව තර කර තිබුණි."),
    q(T, "කුරුණෑගල යුගයේ රචිත 'සිංහල බෝධිවංශය' කෘතියේ කතුවරයා කවුද?", "විලාගමුව තෙරණුවෝ", "ධර්මසේන හිමි", "ශ්‍රී රාහුල හිමි", "ගුරුළුගෝමී", "ජය ශ්‍රී මහා බෝධීන් වහන්සේගේ ඓතිහාසික තොරතුරු විස්තර කරමින් සිංහල බෝධිවංශය ලියැවිණි."),
    q(T, "ගම්පොළ යුගයේදී ගඩලාදෙණිය විහාරය කරවන ලද්දේ කුමන ධර්මධර හිමිනමකගේ අනුශාසනා පරිදිද?", "දෙල්ගමුවේ ධර්මකීර්ති හිමි", "මහානාම හිමි", "බුද්ධඝෝෂ හිමි", "සාරිපුත්ත හිමි", "ධර්මකීර්ති සංඝරාජ හිමියන්ගේ මඟපෙන්වීම යටතේ ගඩලාදෙණි විහාර සංකීර්ණය ගොඩනැංවිණි."),
    q(T, "ගම්පොළ රාජධානියේ අගනුවර ආරක්ෂා කර ගැනීම සඳහා මහවැලි ගඟ ඉටු කළ කාර්යභාරය කුමක්ද?", "ස්වාභාවික දිය අගලක් ලෙස නගරය වටා ආරක්ෂාව සැපයීම", "නැව් ගමනාගමනයට පමණක් යොදා ගැනීම", "කිසිදු ආරක්ෂාවක් නොසැපයීම", "හිම ජලය ගෙන ඒම", "මහවැලි නදියේ වංගුවක් තුළ පිහිටි ගම්පොළ නගරය සතුරන්ට පහසුවෙන් ආක්‍රමණය කළ නොහැකි විය."),
    q(T, "ගම්පොළ යුගයේදී තුන්වන වික්‍රමබාහු රජු සමයේ රටේ ප්‍රධාන බලවතුන් බවට පත්ව සිටි පවුල කුමක්ද?", "අලකේශ්වර (අලගක්කෝනාර) පවුල", "දේවපතිරාජ පවුල", "සෙනෙවිරත්න පවුල", "විජයබාහු පවුල", "කෝට්ටේ හා රයිගම කේන්ද්‍ර කරගත් අලකේශ්වර පරපුර දේශපාලන හා යුද බලය සම්පූර්ණයෙන්ම මෙහෙයවීය."),
    q(T, "රයිගම රාජධානිය කේන්ද්‍ර කරගනිමින් පාලනය කළ අලකේශ්වර පාලකයන් අතර ප්‍රකට වූවෙකු කවුද?", "වීර අලකේශ්වර", "තුන්වන විජයබාහු", "පළමුවන රාජසිංහ", "මායාදුන්නේ", "වීර අලකේශ්වර රයිගම සිට කෝට්ටේ දක්වා බලය පතුරුවා පාලනය ගෙන ගියේය."),
    q(T, "යාපනය රාජධානිය ක්‍රි.ව. 15 වන සියවසේදී ආක්‍රමණය කර කෝට්ටේ රාජධානියට ඈඳාගත් සෙන්පතියා කවුද?", "සපුමල් කුමාරයා (චෙම්බග පෙරුමාල්)", "අලගක්කෝනාර", "වීරබාහු", "මායාදුන්නේ", "හයවන පරාක්‍රමබාහු රජුගේ හදාගත් පුත් සපුමල් කුමරු යාපනය ජයගෙන වසර කිහිපයක් යාපනයේ පාලකයා ලෙස සිටියේය."),
    q(T, "දඹදෙණි යුගයේදී මෙරට වෙළෙඳ කටයුතුවල නිරත වූ ප්‍රධාන විදේශීය වෙළෙඳ ප්‍රජාව වූයේ කවුද?", "මුස්ලිම් (මරක්කල) වෙළෙන්දන්", "පෘතුගීසීන්", "ලන්දේසීන්", "ඉංග්‍රීසීන්", "බටහිර වෙරළබඩ වරායවල් ආශ්‍රිතව අරාබි හා මුස්ලිම් වෙළෙන්දෝ කුළුබඩු වෙළෙඳාමේ නිරත වූහ."),
    q(T, "නිරිතදිග රාජධානි කාලයේදී විහාරස්ථාන හා දේවාල නඩත්තුව සඳහා රජවරුන් පැවරූ ඉඩම් හැඳින්වූයේ කුමන නම්වලින්ද?", "විහාරගම් සහ දේවාලගම්", "නින්දගම් පමණක්", "රජසන්තක ඉඩම්", "බදු ඉඩම්", "පූජනීය ස්ථානවල තේවාවන් හා නඩත්තුව සඳහා ගම්වර පූජා කිරීමේ චාරිත්‍රය පැවතුණි."),
    q(T, "නිරිතදිග රාජධානි යුගයේ රාජ්‍ය සේවය වෙනුවෙන් නිලධාරීන්ට භුක්ති විඳීමට දුන් ඉඩම් හැඳින්වූයේ කුමක් ලෙසද?", "නින්දගම් (හෙවත් පමුණු ඉඩම්)", "අඳ ගොවිතැන්", "බද්ද ඉඩම්", "වල් ඉඩම්", "රජුට පක්ෂපාතීව සේවය කළ ඇමතිවරුන්ට හා ප්‍රභූන්ට නින්දගම් ප්‍රදානය කෙරිණි."),
    q(T, "දඹදෙණි යුගයේ රචිත 'ධාතුවංශය' මගින් විස්තර කෙරෙන්නේ කුමන ධාතූන් වහන්සේ පිළිබඳ ඉතිහාසයද?", "සර්වඥයන් වහන්සේගේ ලළාට ධාතුව (නළල් ධාතුව)", "දන්ත ධාතුව", "කේශ ධාතුව", "ග්‍රීවා ධාතුව", "කකුසඳ, කෝණාගමන, කාශ්‍යප හා ගෞතම බුදුරදුන්ගේ ධාතු විස්තර හා ලළාට ධාතු ඉතිහාසය ධාතුවංශයේ දැක්වේ."),
    q(T, "දඹදෙණි හා ගම්පොළ යුගවලදී රජවරුන් නිතර අගනුවර මාරු කිරීමට හේතු වූ ප්‍රධානතම සමාජීය බලපෑම කුමක්ද?", "දේශපාලන අස්ථාවරත්වය සහ මධ්‍යගත පාලන අධිකාරිය දුර්වල වීම", "ජනගහනය අඩුවීම", "මුදල් අක්‍රිය වීම", "භාෂාව වෙනස් වීම", "නිරන්තර අභ්‍යන්තර ආරවුල් හා විදේශ තර්ජන නිසා එක් ස්ථාවර අගනුවරක දිගු කලක් රැඳී සිටීමට නොහැකි විය."),
    q(T, "යාපහුව පර්වත මුදුනේ පිහිටි නටබුන් අතරින් සාක්ෂි ලැබෙන ගොඩනැගිලි මොනවාද?", "රජ මාළිගාව, මුරපොළවල් හා ස්වාභාවික ජල පොකුණු", "විශාල නැව් තටාක", "විශාල රෝහල්", "කර්මාන්තශාලා", "පර්වත මුදුන ඉතා ආරක්ෂිත සටන් මධ්‍යස්ථානයක් හා නිරීක්ෂණ මුරපොළක් ලෙස සකසා තිබුණි."),
    q(T, "කුරුණෑගල යුගයේ රචනා වූ 'සිංහල ථූපවංශය' කෘතියේ විශේෂත්වය කුමක්ද?", "පාලි ථූපවංශය ඇසුරෙන් රුවන්වැලි සෑය හා බුදුසසුනේ ඉතිහාසය සිංහලෙන් ඉදිරිපත් කිරීම", "යුරෝපීය කතා ඇතුළත් වීම", "හින්දු දේව කතා පමණක් තිබීම", "පද්‍යයෙන් පමණක් ලියැවීම", "පරාක්‍රම පණ්ඩිතයන් විසින් රචිත සිංහල ථූපවංශය ජනප්‍රිය ගද්‍ය කෘතියක් විය."),
    q(T, "ගම්පොළ යුගයේදී දැකගත හැකි වූ සුවිශේෂී ආගමික සහජීවන ලක්ෂණය කුමක්ද?", "බෞද්ධ විහාරස්ථාන තුළම හින්දු දේවාල (උපුල්වන්, සමන්, විභීෂණ, ස්කන්ධ) ඒකාබද්ධව පැවතීම", "සියලු හින්දු කෝවිල් විනාශ කිරීම", "අන්‍ය ආගම් තහනම් කිරීම", "කිසිදු ආගමක් නොඇදහීම", "ලංකාතිලකය හා ගඩලාදෙණිය විහාරවල බුදුමැදුර හා දේවාල එකට පිහිටා තිබීමෙන් මෙය මනාව පැහැදිලි වේ."),
    q(T, "දඹදෙණි යුගයේ දෙවන පරාක්‍රමබාහු රජු විසින් පැවැත්වූ මහා පූජෝත්සවය හැඳින්වෙන්නේ කුමන නමින්ද?", "දළදා පෙරහැර සහ සිරිලක්විජය උත්සවය", "වෙසක් උළෙල පමණක්", "අවුරුදු උත්සවය", "නාවික උළෙල", "දළදා වහන්සේ උදෙසා අති උත්කර්ෂවත් පෙරහැර හා පුද පූජා පැවැත්වීමට රජු පියවර ගත්තේය."),
    q(T, "ගම්පොළ යුගයේදී සිහසුනට පත් හතරවන බුවනෙකබාහු රජු සමඟ එකවර ප්‍රාදේශීයව පාලනය කළ ඔහුගේ සොහොයුරා කවුද?", "පස්වන පරාක්‍රමබාහු රජු (දැදිගම පාලකයා)", "තුන්වන විජයබාහු", "හයවන පරාක්‍රමබාහු", "වීරබාහු", "රාජධානිය බෙදී යාම වළක්වා ගනිමින් සහෝදරයන් දෙදෙනා ගම්පොළ හා දැදිගම සිට එක්ව පාලනය කළහ."),
    q(T, "නිරිතදිග ලංකාවේ රාජධානි බිහිවීමත් සමඟ අභාවයට ගිය පැරණි තාක්ෂණික අංශය කුමක්ද?", "දැවැන්ත වැව් හා දිගු ඇළ මාර්ග ඉදිකිරීමේ මහා වාරි තාක්ෂණය", "ගොවිතැන", "පෙරහැර පැවැත්වීම", "ඇඳුම් මැසීම", "තෙත් කලාපයේ භූ විෂමතාව නිසා මහා පරිමාණ වැව් වෙනුවට කුඩා අමුණු හා දියපාරවල් භාවිතයට ගැනිණි."),
    q(T, "දඹදෙණිය රාජධානියේ නටබුන් අද දැකගත හැක්කේ වර්තමාන කුමන දිස්ත්‍රික්කයේද?", "කුරුණෑගල දිස්ත්‍රික්කයේ", "කළුතර දිස්ත්‍රික්කයේ", "මාතලේ දිස්ත්‍රික්කයේ", "අනුරාධපුර දිස්ත්‍රික්කයේ", "වයඹ පළාතේ කුරුණෑගල දිස්ත්‍රික්කයේ දඹදෙණිය ඓතිහාසික පුරවරය පිහිටා ඇත."),
    q(T, "යාපහුව පර්වත බලකොටුව පිහිටා ඇත්තේ වර්තමානයේ කුමන නගරයට ආසන්නවද?", "මහව නගරය අසල", "ගාල්ල අසල", "හම්බන්තොට අසල", "ත්‍රිකුණාමලය අසල", "කුරුණෑගල දිස්ත්‍රික්කයේ මහව දුම්රිය මංසන්ධියට නුදුරින් යාපහුව පිහිටා ඇත."),
    q(T, "ගම්පොළ රාජධානිය පිහිටා තිබෙන්නේ වර්තමාන කුමන දිස්ත්‍රික්කයේද?", "මහනුවර දිස්ත්‍රික්කයේ", "කෑගල්ල දිස්ත්‍රික්කයේ", "රත්නපුර දිස්ත්‍රික්කයේ", "බදුල්ල දිස්ත්‍රික්කයේ", "මධ්‍යම පළාතේ මහනුවර දිස්ත්‍රික්කයේ මහවැලි නිම්නයේ ගම්පොළ පිහිටා ඇත."),
    q(T, "දඹදෙණි යුගයේ දෙවන පරාක්‍රමබාහු රජු රෝගාතුර වූ විට රාජ්‍ය පාලනය මෙහෙයවූයේ කවුද?", "වීරබාහු සෙන්පතියා සහ දේවපතිරාජ අමාත්‍යවරයා", "චන්ද්‍රභානු", "මාඝ", "ආර්යචක්‍රවර්තී", "රජුගේ අසනීප තත්ත්වය හමුවේ දක්ෂ ඇමතිවරු රටේ ආරක්ෂාව හා පාලනය නොබිඳී ඉදිරියට ගෙන ගියහ."),
    q(T, "දඹදෙණි යුගයේ රචිත 'හත්ථවනගල්ල විහාර වංශය' කෘතියෙන් විස්තර කෙරෙන්නේ කුමන ඓතිහාසික චරිතය ගැනද?", "සිරිසඟබෝ රජුගේ ජීවිත කතාව හා අත්තනගල්ල විහාර ඉතිහාසය", "දුටුගැමුණු රජු", "විජය කුමරු", "මහසෙන් රජු", "සිරිසඟබෝ රජු හිස දන් දුන් අත්තනගල්ල පුදබිමේ ඉතිහාසය මෙයින් විස්තර වේ."),
    q(T, "කුරුණෑගල රාජධානියේ අවසානයට හේතු වූ ප්‍රධාන දේශපාලන සාධකය කුමක්ද?", "රාජකීය අභ්‍යන්තර ආරවුල් සහ ආර්ථික පරිහානිය", "විදේශිකයන් මුහුදෙන් පහර දීම", "ගංවතුර ගැලීම", "වසංගත රෝග පැතිරීම", "පාලකයන් අතර බල අරගල හා දකුණු ඉන්දියානු තර්ජන හමුවේ අගනුවර කඳුකරයට ගෙන යාමට සිදුවිය."),
    q(T, "යාපනය රාජධානියේ ආර්යචක්‍රවර්තී රජවරුන්ගේ මාලිගා නටබුන් අතරින් අදටත් ඉතිරිව ඇත්තේ කුමක්ද?", "සන්ගිලි තෝපුව (නල්ලූර් පිවිසුම් තොරණ)", "දැවැන්ත ප්‍රාසාද", "ගඩොල් ස්තූප", "විශාල පාලම්", "නල්ලූර්හි පිහිටි සන්ගිලි රජුගේ මාලිගයේ පිවිසුම් ආරුක්කුව හා මන්ත්‍රී මනෛ අදටත් දැකගත හැකිය."),
    q(T, "යාපනයේ ආර්යචක්‍රවර්තී පාලකයන් විසින් ඉදිකර නඩත්තු කරන ලද ප්‍රධාන හින්දු සිද්ධස්ථාන මොනවාද?", "නල්ලූර් කන්දසාමි කෝවිල හා මාවිට්ටපුරම් කන්දසාමි කෝවිල", "මුන්නේශ්වරම් පමණක්", "ශ්‍රී පාදය", "කතරගම පමණක්", "හින්දු ආගමික පුනරුදයක් ඇති කරමින් යාපනය පුරා කෝවිල් රැසක් ඉදිකරවන ලදී."),
    q(T, "ගම්පොළ යුගයේදී දැකගත හැකි සුවිශේෂී කලා අංගයක් වන 'ගඩලාදෙණියේ සෙල්ලිපිය' කොටා ඇත්තේ කුමන ස්ථානයකද?", "ස්වාභාවික කළුගල් පර්වත මතුපිට", "ලී කුළුණුවල", "තඹ තහඩුවල", "මැටි බඳුන්වල", "විහාර මළුවේ පිහිටි දැවැන්ත කළුගල් පර්වතය මත ධර්මකීර්ති හිමියන් කළ සේවාවන් කොටා ඇත."),
    q(T, "දඹදෙණි යුගයේ දෙවන පරාක්‍රමබාහු රජු විසින් උපසම්පදාව නැවත පිහිටුවීම සඳහා භික්ෂූන් වැඩම කරවූයේ කුමන රටෙන්ද?", "බුරුමයෙන් (රාමඤ්ඤ දේශයෙන්) සහ චෝල දේශයෙන්", "චීනයෙන්", "ජපානයෙන්", "නේපාලයෙන්", "පිරිහී තිබූ සංඝ සමාජය යළි පිහිටුවීමට විදේශීය ධර්මධර මහ තෙරවරුන්ගේ සහාය ලබා ගත්තේය."),
    q(T, "යාපහුව රාජධානියේ බිත්ති සහ වාහල්කඩවල නිරූපණය කර ඇති කාන්තා නර්තන කැටයම්වල විශේෂත්වය කුමක්ද?", "භාරතීය භරත නාට්‍ය හා දේශීය නර්තන සම්ප්‍රදායන් මිශ්‍ර වූ අලංකාර ඉරියව්", "යුරෝපීය නැටුම්", "බටහිර මුද්‍රා", "චීන නැටුම් පමණක්", "නළඟනන්ගේ නම්‍යශීලී සිරුරු හා සංගීත භාණ්ඩ වාදනය ඉතා සියුම් ලෙස ගලින් නෙළා ඇත."),
    q(T, "ගම්පොළ යුගයේදී බිහිවූ අලංකාර දැව කැටයමක් වන 'ඇත් කඳ ලිහිණියා' යනු කුමක්ද?", "අලියෙකු ඔසවාගෙන යන දැවැන්ත මිථ්‍යා පක්ෂියෙකි", "සාමාන්‍ය පක්ෂියෙකි", "මාළුවෙකි", "ගවයෙකි", "ඇම්බැක්කේ දැව කුළුණුවල හමුවන මෙම කැටයම ශක්තිය හා අද්භූත බව නිරූපණය කරයි."),
    q(T, "නිරිතදිග රාජධානි යුගයේ සාහිත්‍යය වඩාත් ජනප්‍රිය වීමට බලපෑ භාෂාමය හේතුව කුමක්ද?", "සංස්කෘත බර වචන වෙනුවට සාමාන්‍ය ගැමි ජනතාවට තේරුම් ගත හැකි සරල සිංහල බස භාවිත වීම", "ඉංග්‍රීසි මිශ්‍ර වීම", "පාලි පමණක් භාවිත වීම", "ලතින් බස මුසු වීම", "ජනතාව අතර ධර්මය ප්‍රචලිත කිරීම සඳහා බුත්සරණ, සද්ධර්මරත්නාවලිය, ජාතක පොත ආදිය සරල ජන බසින් ලියැවිණි."),
    q(T, "කුරුණෑගල යුගයේදී රජකළ හතරවන පරාක්‍රමබාහු රජු දළදා මාලිගාව ඉදිකළේ නගරයේ කුමන ස්ථානයේද?", "ඇතුගල පාමුල රජ මාලිගා පරිශ්‍රයේ", "පර්වත මුදුනේ", "ගං ඉවුරේ", "නගරයෙන් පිටත", "දළදා වහන්සේ තම ආරක්ෂාව යටතේ තබා ගනිමින් රාජ්‍යත්වයේ සංකේතය ලෙස වැඳුම් පිදුම් කළේය."),
    q(T, "දඹදෙණි යුගයේදී තුන්වන විජයබාහු රජු විසින් ප්‍රතිසංස්කරණය කරන ලද කැළණි විහාරයේ ස්තූපය විනාශ කර තිබුණේ කා විසින්ද?", "කාලිංග මාඝගේ හමුදාව විසින්", "චෝලයින් විසින්", "පෘතුගීසීන් විසින්", "ලන්දේසීන් විසින්", "මාඝගේ ආක්‍රමණිකයන් මායා රටේ විහාර විනාශ කළ අතර විජයබාහු රජු කැළණිය යළි පිළිසකර කළේය."),
    q(T, "දඹදෙණි යුගයේදී ජනතාව අතර බහුලව භාවිත වූ ප්‍රවාහන මාධ්‍යයක් වූයේ කුමක්ද?", "ගොන් කරත්ත, ඔරු පාරු සහ පාගමන", "දුම්රිය", "මෝටර් රථ", "ගුවන් යානා", "ගංගා දිගේ ඔරු මගින් භාණ්ඩ ප්‍රවාහනය කිරීම තෙත් කලාපයේ ප්‍රධාන මාවතක් විය."),
    q(T, "ගම්පොළ යුගයේදී රචනා වූ 'මයුර සන්දේශය' මගින් ආශීර්වාද පතන ලද්දේ කුමන ප්‍රභූවරයාටද?", "තුන්වන වික්‍රමබාහු රජුට සහ අලගක්කෝනාර ඇමතිට", "දෙවන පරාක්‍රමබාහුට", "හයවන පරාක්‍රමබාහුට", "මායාදුන්නේට", "රටේ ආරක්ෂාව හා රජුගේ ආයු වර්ධනය පතා දෙවුන්දර උපුල්වන් දෙවියන්ට කන්නලව් කරමින් පණිවුඩය යැවීය."),
    q(T, "නිරිතදිග රාජධානි කාලයේදී ලංකාවට පැමිණි විදේශීය වෙළෙඳුන් මිලදී ගැනීමට වඩාත්ම උනන්දු වූ භාණ්ඩය කුමක්ද?", "කුරුඳු, ඇත්දළ, මැණික් හා පුවක්", "රෙදිපිළි පමණක්", "ලුණු", "තේ", "ලංකාවේ උසස් තත්ත්වයේ කුරුඳු ලෝක වෙළෙඳපොළේ ඉහළම ඉල්ලුමක් දිනාගෙන තිබුණි."),
    q(T, "දඹදෙණි යුගයේ පැවති පරිපාලන ක්‍රමයේදී ගම පාලනය කළ ප්‍රධානියා හැඳින්වූයේ කුමන නමින්ද?", "ගම්ලද්දා (ගම්මුලාදෑනි)", "දිසාව", "අදිකාරම්", "මුහන්දිරම්", "ගමේ බදු එකතු කිරීම හා නීතිය සාමය රැකීම ගම්ලද්දාට පැවරී තිබුණි."),
    q(T, "යාපහුව රාජධානියේ නටබුන් අතරින් හමුවූ විදේශීය කාසි විශේෂය කුමක්ද?", "චීන කාසි (සුං සහ යුවාන් රාජවංශ කාසි)", "රෝම කාසි පමණක්", "ඇමරිකන් කාසි", "ජපන් කාසි", "චීනය සමඟ පැවති සෘජු වෙළෙඳ සබඳතා තහවුරු කරමින් චීන පිඟන් මැටි හා කාසි හමුවිය."),
    q(T, "කුරුණෑගල යුගයේදී 'ඇතුගල' පර්වතය රාජධානියට ලබාදුන් ප්‍රධාන වාසිය කුමක්ද?", "සතුරන් එන දෙස ඈත තබා නිරීක්ෂණය කළ හැකි ස්වාභාවික ආරක්ෂක මුර අට්ටාලයක් වීම", "වී ගොවිතැන් කිරීමට හැකිවීම", "මුහුදු නැව් නැවැත්විය හැකිවීම", "හිම ක්‍රීඩා කළ හැකිවීම", "පර්වතය මත සිට මුළු ප්‍රදේශයම නිරීක්ෂණය කර සතුරු ආක්‍රමණවලට පෙර සූදානම් විය හැකි විය."),
    q(T, "නිරිතදිග රාජධානි යුගයේ රජවරුන් දළදා වහන්සේ තම රාජධානියේම තබා ගැනීමට දැඩි උත්සාහයක් ගත්තේ ඇයි?", "දළදා හිමිකම රාජ්‍යත්වයේ අනිවාර්ය නීත්‍යානුකූල සංකේතය බවට පත්ව තිබූ බැවින්", "එය සාමාන්‍ය වස්තුවක් වූ බැවින්", "විකිණීමට අවශ්‍ය වූ නිසා", "විදේශිකයන් ඉල්ලා සිටි නිසා", "දළදා වහන්සේ සන්තකයේ නැති රජෙකුට සිංහාසනයේ නීත්‍යානුකූල උරුමය නොලැබුණි."),
    q(T, "දඹදෙණි යුගයේ සාහිත්‍ය නිර්මාණ අතර උපමා හා ගැමි කියමන් බහුලව යොදාගත් කෘතිය කුමක්ද?", "සද්ධර්මරත්නාවලිය", "කව්සිළුමිණ", "සිදත් සඟරාව", "සමන්තකූට වණ්ණනාව", "ධර්මසේන හිමියන් ගැමියන්ගේ එදිනෙදා ජීවිතයේ අත්දැකීම් උපමා කරමින් ධර්මය පහදා දුන්හ."),
    q(T, "ගම්පොළ යුගයේදී අලගක්කෝනාර විසින් කෝට්ටේ තැනූ බලකොටුව පසුකාලීනව 'කෝට්ටේ රාජධානිය' බවට පත්වීමට ප්‍රධාන හේතුව කුමක්ද?", "එහි පැවති අසමසම ආරක්ෂිත පිහිටීම හා බටහිර මුහුදු වෙළෙඳ මාර්ගවලට සමීප වීම", "එය කඳු මුදුනක පිහිටීම", "එහි විශාල වැව් තිබීම", "ශීත දේශගුණය", "ආරක්ෂාව මෙන්ම කොළඹ වරාය හරහා විදේශ වෙළෙඳාම පාලනය කිරීමට කෝට්ටේ මූලෝපායික විය."),
    q(T, "දඹදෙණි යුගයේ තුන්වන විජයබාහු රජුගේ පියා කවුරුන්දැයි වංශකතාවල සඳහන් වන්නේ කුමක් ලෙසද?", "සිරිසඟබෝ රජ පරපුරෙන් පැවත එන විජයමල්ල කුමරු", "චෝල රජෙක්", "පාණ්ඩ්‍ය කුමරෙක්", "කාලිංග මාඝ", "තුන්වන විජයබාහු රජු සිරිසඟබෝ පරපුරේ ක්ෂත්‍රිය කුමාරයෙකු ලෙස සිංහාසනාරූඪ විය."),
    q(T, "මාඝගේ පාලන කාලයේදී බෞද්ධ භික්ෂූන් වහන්සේලා ධර්ම ග්‍රන්ථ ආරක්ෂා කර ගැනීම සඳහා රැගෙන ගිය ප්‍රධාන ප්‍රදේශ මොනවාද?", "මායා රට සහ රුහුණු රටේ ආරණ්‍ය සේනාසන", "යාපනය පමණක්", "ඉන්දියාව පමණක්", "මුහුදු වෙරළ", "මාඝගේ භටයන් පොත්පත් ගිනි තබද්දී භික්ෂූන් කොත්මලේ හා දකුණේ කඳුකර ආරණ්‍යවලට ඒවා රැගෙන ගියහ."),
    q(T, "තුන්වන විජයබාහු රජු විසින් බෙලිගල පර්වතය මත කරවන ලද දළදා මැදුරේ ආරක්ෂාව භාර කළේ කා හටද?", "සංඝරක්ෂිත මහ තෙරුන් ඇතුළු මහා සංඝරත්නයට", "විදේශීය සෙබළුන්ට", "වෙළෙඳුන්ට", "ගොවීන්ට", "රජු දළදා මැදුර වටා ප්‍රාකාර හා මුරපොළවල් තනා සංඝරත්නයේ රැකවරණයට භාර කළේය."),
    q(T, "දෙවන පරාක්‍රමබාහු රජු සිහසුනට පත්වූ විගස රාජධානියේ සාමය තහවුරු කිරීම සඳහා කළ ප්‍රථම කාර්යය කුමක්ද?", "මාඝගේ සහ ජයබාහුගේ බලකොටු වටලා ඔවුන් රටින් පලවා හැරීම", "නව බදු පැනවීම", "විදේශ වෙළෙඳාම නැවැත්වීම", "විහාර විනාශ කිරීම", "පොළොන්නරුව හා රජරට මුදාගෙන මුළු දිවයිනම එක්සේසත් කිරීමට රජු සමත් විය."),
    q(T, "දෙවන පරාක්‍රමබාහු රජුගේ කාලයේ චන්ද්‍රභානු දෙවන වරට ලංකාව ආක්‍රමණය කළේ කාගේ සහාය ඇතිවද?", "පාණ්ඩ්‍ය හා චෝල කුලී හේවායන්ගේ සහාය ඇතිව", "චීන හමුදාවේ සහාය ඇතිව", "පෘතුගීසීන්ගේ සහාය ඇතිව", "ලන්දේසීන්ගේ සහාය ඇතිව", "දකුණු ඉන්දියානු කුලී හමුදා සමඟ පැමිණි චන්ද්‍රභානු යාපහුව ආක්‍රමණය කිරීමට උත්සාහ කළේය."),
    q(T, "චන්ද්‍රභානුගේ දෙවන ආක්‍රමණයේදී ඔහු මරා දමා සම්පූර්ණ ජයග්‍රහණය අත්කර ගත් සිංහල කුමාරවරුන් දෙදෙනා කවුද?", "වීරබාහු කුමරු සහ විජයබාහු කුමරු (බෝසත් විජයබාහු)", "පළමු බුවනෙකබාහු සහ දෙවන බුවනෙකබාහු", "මාඝ හා ජයබාහු", "මිත්ත හා ඨකුරක", "දෙවන පරාක්‍රමබාහුගේ පුත් විජයබාහු සහ බෑණනුවන් වූ වීරබාහු චන්ද්‍රභානු මරා ජාවක හමුදාව විනාශ කළහ."),
    q(T, "දඹදෙණි යුගයේ දෙවන පරාක්‍රමබාහු රජු විසින් අලුත්වැඩියා කරන ලද පැරණි සිද්ධස්ථානයක් නොවන්නේ කුමක්ද?", "මහනුවර දළදා මාලිගය", "කැළණි රජමහා විහාරය", "රුවන්වැලි මහා සෑය", "ශ්‍රී මහා බෝධිය", "මහනුවර දළදා මාලිගය පසුකාලීනව ඉදිවූවක් වන අතර අනුරාධපුර හා කැළණි විහාර රජු ප්‍රතිසංස්කරණය කළේය."),
    q(T, "දෙවන පරාක්‍රමබාහු රජු විසින් දඹදෙණියේ සිට පොළොන්නරුව දක්වා මාර්ගය පිළිසකර කරවූයේ කුමන අරමුණක් සඳහාද?", "දන්ත ධාතුව හා පාත්‍රා ධාතුව පොළොන්නරුවට වැඩමවා රාජාභිෂේකය පැවැත්වීමට", "යුද්ධයකට යාමට", "වෙළෙඳුන් පලවා හැරීමට", "රට හැර යාමට", "තම මුතුන්මිත්තන්ගේ අගනුවර වූ පොළොන්නරුවේදී උත්සවාකාරයෙන් අභිෂේක ලැබීමට රජු පියවර ගත්තේය."),
    q(T, "බෝසත් විජයබාහු (හතරවන විජයබාහු) රජු පොළොන්නරුව ප්‍රතිසංස්කරණය කර එහි පාලකයා ලෙස පත් කළේ කා හටද?", "තම බාල සොහොයුරු පළමුවන බුවනෙකබාහු කුමරුට", "වීරබාහු කුමරුට", "දේවපතිරාජ ඇමතිට", "මිත්ත සෙන්පතියාට", "පොළොන්නරුවේ පාලනය බුවනෙකබාහුට භාර දී රජු නැවත දඹදෙණියට පැමිණියේය."),
    q(T, "මිත්ත සෙන්පතියා හතරවන විජයබාහු රජු ඝාතනය කළේ කුමන ස්ථානයේදීද?", "දඹදෙණි රාජ මාළිගාවේදී", "යාපහුවේදී", "කුරුණෑගලදී", "ගම්පොළදී", "කුමන්ත්‍රණකාරී ලෙස මිත්ත සෙන්පතියා කුලී ඝාතකයෙකු යොදවා රජු මරා දැමීය."),
    q(T, "පළමුවන බුවනෙකබාහු රජු දඹදෙණියෙන් යාපහුවට අගනුවර මාරු කිරීමට තීරණය කළ ප්‍රධාන සාධකය කුමක්ද?", "දඹදෙණියේ ආරක්ෂාව ප්‍රමාණවත් නොවීම සහ යාපහුව ස්වාභාවික කළුගල් පර්වතයක් වීම", "දඹදෙණියේ වතුර නැතිවීම", "යාපහුවේ මුහුදක් තිබීම", "සීතල වැඩිවීම", "ආරක්ෂාව අතින් වඩාත් ශක්තිමත් උස් පර්වතයක් වූ සුභ පබ්බතය (යාපහුව) තෝරා ගත්තේය."),
    q(T, "යාපහුව පර්වත මුදුනට නැගීමට තනා ඇති දැවැන්ත පියගැට පෙළේ කොටස් කීයක් ඇත්ද?", "ප්‍රධාන පියගැට පෙළ අදියර තුනකින් සමන්විතය", "එක් පියගැට පෙළක් පමණි", "පියගැට පෙළ දහයක්", "පියගැට පෙළ විස්සක්", "පහළ මළුවේ සිට ඉහළ දළදා මැදුර දක්වා විචිත්‍ර කැටයම් සහිත අදියර තුනකින් යුත් පියගැට පෙළ විහිදේ."),
    q(T, "යාපහුව දළදා මැදුරේ දොරටුවේ දෙපස පිහිටුවා ඇති ගජසිංහ කොරවක්ගල්වල ඇති විශේෂත්වය කුමක්ද?", "ඇත් හොඬවැලක් සහ සිංහ ශරීරයක් සහිත මනරම් මිශ්‍ර සත්ත්ව කැටයමක් වීම", "සාමාන්‍ය ගල් පුවරුවක් වීම", "ලීයෙන් නෙළා තිබීම", "මැටියෙන් තනා තිබීම", "ගජසිංහ කැටයම ශක්තිය හා ගාම්භීරත්වය විදහාපාන අද්විතීය කලා කෘතියකි."),
    q(T, "යාපහුවෙන් හමුවූ චීන සෙරමික් (පිඟන් භාණ්ඩ) කැබලි තුළින් තහවුරු වන්නේ කුමක්ද?", "සුං හා යුවාන් රාජවංශ සමයේ චීනය සමඟ පැවති සමීප වෙළෙඳ සබඳතා", "චීනය ලංකාව යටත් කරගත් බව", "චීන සොල්දාදුවන් එහි වාසය කළ බව", "චීන භාෂාව මෙරට රාජ්‍ය භාෂාව වූ බව", "චීනයෙන් ආනයනය කරන ලද වටිනා පෝසිලේන් භාණ්ඩ රාජකීයයන් භාවිත කළ බව මින් තහවුරු වේ."),
    q(T, "ඊජිප්තු සුල්තාන්වරයා වෙත පළමුවන බුවනෙකබාහු රජු යැවූ වෙළෙඳ සංදේශය ලියා තිබුණේ කුමන භාෂාවෙන්ද?", "අරාබි භාෂාවෙන්", "සිංහල භාෂාවෙන්", "පාලි භාෂාවෙන්", "ලතින් භාෂාවෙන්", "සුල්තාන් අල් මුස්තන්සීර්ගේ ලේඛනාගාරයේ තිබී හමුවූ මෙම ලිපිය අරාබි බසින් ලියා තිබුණි."),
    q(T, "පාණ්ඩ්‍ය සෙන්පති ආර්යචක්‍රවර්තී යාපහුව අල්ලා ගත් විට දළදා වහන්සේ භාර දුන්නේ කුමන රජුටද?", "පාණ්ඩ්‍ය රජ කුලසේකරට (මදුරෙයි නුවරදී)", "චෝල රජුට", "චීන අධිරාජයාට", "ඊජිප්තු සුල්තාන්ට", "පාණ්ඩ්‍ය අධිරාජ්‍යයේ අගනුවර වූ මදුරෙයි නුවරට දළදාව රැගෙන ගොස් කුලසේකර රජුට භාර දුන්නේය."),
    q(T, "තුන්වන පරාක්‍රමබාහු රජු දළදා වහන්සේ ආපසු ගෙන ඒම සඳහා මදුරෙයි නුවරට ගියේ කෙසේද?", "කිසිදු සේනාවක් නොමැතිව සාමකාමී තානාපති පිරිසක් සමඟ", "දැවැන්ත ආක්‍රමණික හමුදාවක් සමඟ", "රහසිගතව හොරෙන්", "වෙළෙන්දෙකු ලෙස", "තම බුද්ධිමත් රාජ්‍ය තාන්ත්‍රික සාකච්ඡා තුළින් පාණ්ඩ්‍ය රජු පැහැදවීමට තුන්වන පරාක්‍රමබාහු සමත් විය."),
    q(T, "තුන්වන පරාක්‍රමබාහු රජු විසින් දළදා වහන්සේ යළි වැඩමවා තැන්පත් කළේ කුමන නගරයේද?", "පොළොන්නරුවේ අටදාගේ මැදුරේ", "යාපහුවේ", "දඹදෙණියේ", "කොළඹ", "දළදා වහන්සේ මහත් හරසරින් වැඩමවා පොළොන්නරුවේ තැන්පත් කර පුද පූජා පැවැත්වීය."),
    q(T, "කුරුණෑගල රාජධානිය පිහිටුවූ දෙවන බුවනෙකබාහු රජුගේ පියා කවුද?", "පළමුවන බුවනෙකබාහු රජු", "දෙවන පරාක්‍රමබාහු රජු", "තුන්වන විජයබාහු රජු", "මිත්ත සෙන්පතියා", "යාපහුවේ රජකළ පළමුවන බුවනෙකබාහුගේ පුත් දෙවන බුවනෙකබාහු කුරුණෑගල අගනුවර කරගත්තේය."),
    q(T, "කුරුණෑගල යුගයේ රජකළ හතරවන පරාක්‍රමබාහු රජුගේ ගුරු හිමිනම වූයේ කවුද?", "චෝල දේශයෙන් වැඩම කළ ධර්මකීර්ති නම් මහා ස්ථවිරයන් වහන්සේ", "මහානාම හිමි", "මිහිඳු හිමි", "බුද්ධඝෝෂ හිමි", "විදේශීය ධර්මධර පඬිවරුන්ගේද සහාය ලබමින් රජු ත්‍රිපිටක ධර්මය හා සාහිත්‍යය ගැඹුරින් හැදෑරීය."),
    q(T, "හතරවන පරාක්‍රමබාහු රජු විසින් සිංහලයට පරිවර්තනය කරවන ලද 'පන්සිය පනස් ජාතක පොතේ' මුල් භාෂාව කුමක්ද?", "පාලි භාෂාව (ජාතකට්ඨකතාව)", "සංස්කෘත භාෂාව", "දෙමළ භාෂාව", "හින්දි භාෂාව", "පාලි ජාතක අටුවාව සිංහල ගැමි වහරට මුසු කරමින් විචිත්‍රවත් ගද්‍ය කෘතියක් ලෙස නිමවන ලදී."),
    q(T, "හතරවන පරාක්‍රමබාහු රජුගේ නියමයෙන් ලියැවුණු 'දළදා සිරිත' ග්‍රන්ථයේ ඇතුළත් ප්‍රධාන කරුණු මොනවාද?", "දළදා වහන්සේගේ ඉතිහාසය සහ දිනපතා හා වාර්ෂිකව කළ යුතු පුද පූජා චාරිත්‍ර නීති මාලාව", "යුද නීති", "විදේශ වෙළෙඳ නීති", "ගොවිතැන් ක්‍රම", "දළදා වහන්සේ උදෙසා රජවරුන් හා නිලධාරීන් ඉටු කළ යුතු වගකීම් ව්‍යවස්ථාවක් ලෙස මෙහි දක්වා ඇත."),
    q(T, "කුරුණෑගල යුගයේදී රචිත තවත් ප්‍රකට ධර්ම ග්‍රන්ථයක් වන්නේ කුමක්ද?", "සිංහල බෝධිවංශය සහ අනාගතවංශය", "අමාවතුර", "බුත්සරණ", "ධර්මප්‍රදීපිකාව", "විලාගමුව තෙරුන් විසින් සිංහල බෝධිවංශය රචනා කරන ලද්දේ මෙම යුගයේදීය."),
    q(T, "හතරවන බුවනෙකබාහු රජු ගම්පොළ නගරය අගනුවර කරගත්තේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 1341 දී පමණ", "ක්‍රි.ව. 1215 දී", "ක්‍රි.ව. 1505 දී", "ක්‍රි.ව. 1017 දී", "කුරුණෑගලින් පසු මධ්‍යම කඳුකරයේ පිහිටි ගම්පොළ නගරය අගනුවර බවට පත්විය."),
    q(T, "ගම්පොළ යුගයේදී ඉදිවූ 'ගඩලාදෙණිය විහාරයේ' බුද්ධ ප්‍රතිමාව නෙළා ඇත්තේ කුමන ඉරියව්වෙන්ද?", "මකර තොරණක් යට වැඩසිටින සමාධි (ධ්‍යාන) මුද්‍රාවෙන්", "හිටි පිළිමයක් ලෙස", "සැතපෙන පිළිමයක් ලෙස", "අභය මුද්‍රාවෙන්", "කළුගලින් නෙළන ලද දැවැන්ත සමාධි පිළිමය දෙපස දෙවිවරුන්ගේ රූප සහිත මකර තොරණක් ඇත."),
    q(T, "ගඩලාදෙණිය විහාරය සම්පූර්ණයෙන්ම ගලින් නිමවා ඇති බැවින් එය හැඳින්වූ පැරණි නාමය කුමක්ද?", "සද්ධර්මතිලක විහාරය (ගල් විහාරය)", "ලෝවාමහාපාය", "රත්නප්‍රාසාදය", "විජයසුන්දරාරාමය", "සෙල්ලිපිවල මෙම විහාරය 'ධර්මකීර්ති සද්ධර්මතිලක විහාරය' ලෙස හඳුන්වා ඇත."),
    q(T, "ගම්පොළ යුගයේ ලංකාතිලක විහාරයේ සෙල්ලිපියෙහි සඳහන් වන ප්‍රධාන ලක්ෂණය කුමක්ද?", "එකම සෙල්ලිපිය සිංහල හා දෙමළ භාෂා දෙකෙන්ම කොටා තිබීම", "ඉංග්‍රීසි බසින් තිබීම", "චීන බසින් තිබීම", "ලතින් බසින් තිබීම", "සමකාලීන බහුභාෂා භාවිතය හා සමාජ සංයුතිය මෙයින් පැහැදිලි වේ."),
    q(T, "ඇම්බැක්කේ දේවාලයේ දැව කැටයම් සඳහා යොදාගත් ප්‍රධාන දැව වර්ග මොනවාද?", "ගංසූරිය, නා, හල්මිල්ල හා කොස් දැව", "පොල් දැව පමණක්", "රබර් දැව", "පයින් දැව", "කල්පවතින ශක්තිමත් දැව වර්ග තෝරාගෙන සියුම් කැටයම් නෙළා ඇත."),
    q(T, "ඇම්බැක්කේ දේවාලයේ වහල නිර්මාණයේ ඇති ඉංජිනේරුමය විශිෂ්ටත්වය කුමක්ද?", "මඩොල් කුරුපාව (සියලු පරාල එකතු වන තනි ලී ඇණය)", "යකඩ බෝල්ට් ඇණ", "සිමෙන්ති බදාම", "වීදුරු ආධාරක", "ලී පරාල 26ක් එකට රඳවා තබන 'මඩොල් කුරුපාව' පැරණි සිංහල දැව වඩු ශිල්පයේ විශිෂ්ට මුදුන් මල්කඩකි."),
    q(T, "තුන්වන වික්‍රමබාහු රජුගේ බිසව වූ 'හේනකඳ බිසෝ බණ්ඩාර' දේවිය හා සම්බන්ධ සිද්ධස්ථානය කුමක්ද?", "ඇම්බැක්කේ දේවාලය සහ මැදවල විහාරය", "කැළණි විහාරය", "රුවන්වැලිසෑය", "නාගදීපය", "ඇම්බැක්කේ දේවාලයට ඉඩකඩම් පූජා කරමින් දේවාලය ඉදිකිරීමට ඇය දායක වූවාය."),
    q(T, "දැදිගම කොටවෙහෙර කරවන ලද පස්වන පරාක්‍රමබාහු රජුගේ පාලන ප්‍රදේශය වූයේ කුමක්ද?", "දක්ෂිණදේශය (මායා රට)", "රුහුණ", "පිහිටි රට", "යාපනය", "හතරවන බුවනෙකබාහු ගම්පොළ රජ කරන විට පස්වන පරාක්‍රමබාහු දැදිගම සිට පාලනය කළේය."),
    q(T, "දැදිගම ඇත් පහනේ ඉංජිනේරුමය ක්‍රියාකාරිත්වය සිදුවන්නේ කුමන භෞතික විද්‍යා මූලධර්මය මතද?", "වායුගෝලීය පීඩනය සහ ද්‍රවස්ථිති මූලධර්මය (Hydrostatic principle)", "විදුලි බලය", "චුම්භක බලය", "තාප සංවහනය", "පහනේ තෙල් වැටෙන විට ඇතුළත රික්තකය නිසා තෙල් මට්ටම ස්වයංක්‍රීයව පාලනය වේ."),
    q(T, "අලගක්කෝනාර අමාත්‍යවරයා පැවත ආවේ කුමන පෙළපතකින්ද?", "භාරතයේ වංචිපුරයෙන් මෙරටට පැමිණ පැලපදියම් වූ ප්‍රභූ වෙළෙඳ පෙළපතකින්", "පෘතුගීසි පරපුරකින්", "චීන පරපුරකින්", "රෝම පරපුරකින්", "ගිරිවංශයට අයත් අලකේශ්වර පරපුර ලංකාවේ බුදුසසුන හා දේශපාලනය ආරක්ෂා කිරීමට පෙරමුණ ගත්හ."),
    q(T, "කෝට්ටේ බලකොටුව ඉදිකිරීමේදී ප්‍රධාන ගොඩනැගිලි ද්‍රව්‍යය ලෙස යොදාගත්තේ කුමක්ද?", "කබොක් ගල් (Laterite stones)", "කළුගල් පමණක්", "ගඩොල් පමණක්", "දැව පමණක්", "කපා හැඩ ගැස්වීමට පහසු මෙන්ම වියළි විට අතිශය දැඩි වන කබොක් ගල් ප්‍රාකාර බැඳීමට යොදාගත්තේය."),
    q(T, "කෝට්ටේ ඇතුළු නුවර වටා ඉදිකළ ප්‍රාකාරය හැඳින්වූයේ කුමන නමින්ද?", "දියවන්නා බැම්ම හා කබොක් ප්‍රාකාරය", "චීන මහා ප්‍රාකාරය", "සීගිරි පවුර", "ගල්පොත", "කෝට්ටේ යන නමම 'කොට්ටෙයි' හෙවත් බලකොටුව යන දෙමළ වචනයෙන් බිඳී ආවක් බව සැලකේ."),
    q(T, "ආර්යචක්‍රවර්තීගේ හමුදා කෝට්ටේ ආක්‍රමණය කළ අවස්ථාවේදී අලගක්කෝනාර සේනා මෙහෙයවූයේ කෙසේද?", "කෝට්ටේ බලකොටුව තුළ සුරක්ෂිතව සිටිමින් ප්‍රතිප්‍රහාර එල්ල කර සතුරා විනාශ කිරීමෙන්", "රට පාවා දීමෙන්", "පලා යාමෙන්", "සටන් නොකර යටත් වීමෙන්", "පෙර සූදානමකින් යුතුව ආහාර හා අවි ආයුධ රැස්කර තිබූ බැවින් පහසුවෙන් ආක්‍රමණිකයන් පරාජය කළේය."),
    q(T, "ගම්පොළ යුගයේදී රචිත 'තිසර සන්දේශය' මගින් කුරුළු දූතයා ගමන් කළේ කොතැන සිට කොතැනටද?", "දෙවුන්දර සිට ගම්පොළ දක්වා", "ගාල්ලේ සිට යාපනයට", "කොළඹ සිට නුවරට", "කතරගම සිට අනුරාධපුරයට", "දෙවුන්දර උපුල්වන් දෙවියන්ගේ ආශීර්වාදය පස්වන පරාක්‍රමබාහු රජුට ලබා දීමට දූතයා ගමන් කළේය."),
    q(T, "චීන සෙන්පති චෙං හෝ විසින් ලංකාවෙන් රැගෙන ගිය වීර අලකේශ්වර වෙනුවට මිං අධිරාජයා පත් කිරීමට නිර්දේශ කළේ කා හටද?", "පරාක්‍රමබාහු කුමරුට (පසුව හයවන පරාක්‍රමබාහු බවට පත් වූ)", "ආර්යචක්‍රවර්තීට", "මාඝට", "සපුමල් කුමරුට", "චීනයෙන් නිදහස් කර එවන ලද රාජකීය උරුමක්කාරයා හයවන පරාක්‍රමබාහු ලෙස කෝට්ටේ රජවිය."),
    q(T, "යාපනය අර්ධද්වීපයේ පිහිටි පැරණිතම බෞද්ධ නටබුන් සහිත ස්ථානයක් වන්නේ කුමක්ද?", "කඳුරුගොඩ (කන්දරෝඩෙයි) විහාරය", "නල්ලූර් කෝවිල", "නාගදීපය පමණක්", "කයිට්ස්", "කන්දරෝඩෙයි ප්‍රදේශයෙන් කුඩා ස්තූප රැසක් හා පුරාණ බෞද්ධ නටබුන් හමුවී ඇත."),
    q(T, "යාපනය රාජධානිය හා දකුණු ඉන්දියාව අතර මගීන් හා භාණ්ඩ ප්‍රවාහනය කළ ප්‍රධාන වරාය කුමක්ද?", "ජම්බුකෝලපට්ටන (දඹකොළපටුන) සහ ඌරාතොට (කයිට්ස්)", "කොළඹ", "ගාල්ල", "ත්‍රිකුණාමලය", "කයිට්ස් හෙවත් ඌරාතොට අශ්වයන් හා ඇතුන් වෙළෙඳාම් කළ ප්‍රධාන ජාත්‍යන්තර තොටුපළක් විය."),
    q(T, "යාපනය රාජධානියේ ආර්යචක්‍රවර්තී රජවරුන් බදු අය කළ ප්‍රධාන වෙළෙඳ භාණ්ඩයක් වූයේ කුමක්ද?", "දුම්කොළ, ලුණු, මුතු සහ අලි ඇතුන්", "තේ", "කෝපි", "රබර්", "මන්නාරමේ මුතු කිමිදීමෙන් හා යාපනයේ ලුණු ලේවායන්ගෙන් රජයට විශාල ආදායමක් එකතු විය."),
    q(T, "නිරිතදිග රාජධානි කාලයේදී ගම් මට්ටමින් පැවති ආරවුල් විසඳූ සාම්ප්‍රදායික ආයතනය කුමක්ද?", "ගම් සභාව (ගම සභාව)", "ශ්‍රේෂ්ඨාධිකරණය", "පොලිසිය", "යුද හමුදාව", "ගමේ වැඩිහිටියන් හා ප්‍රධානීන් එක්වී ඉඩම් හා සුළු ආරවුල් ගම් සභාවේදී සමථයකට පත් කළහ."),
    q(T, "නිරිතදිග රාජධානි යුගයේ බිහිවූ 'විද්‍යාපීඨ' හෙවත් මහා පිරිවෙන් අධ්‍යාපනයේ මූලික ලක්ෂණය කුමක්ද?", "ත්‍රිපිටකය, ව්‍යාකරණ, ඡන්දස්, අලංකාර, තාරකා විද්‍යාව හා ආයුර්වේදය ඉගැන්වීම", "ඉංග්‍රීසි පමණක් ඉගැන්වීම", "යුද අභ්‍යාස පමණක් කිරීම", "විදේශ භාෂා තහනම් වීම", "පිරිවෙන් මගින් භික්ෂූන් හා ගිහි ප්‍රභූ දරුවන්ට උසස් ශාස්ත්‍රීය අධ්‍යාපනයක් ලබා දුන්නේය."),
    q(T, "දඹදෙණි යුගයේ දෙවන පරාක්‍රමබාහු රජුට 'කලිකාල සාහිත්‍ය සර්වඥ පණ්ඩිත' යන නාමය හිමිවීමට හේතුව කුමක්ද?", "එකල පැවති සියලු සාහිත්‍ය හා ශාස්ත්‍රීය විෂයන්හි කෙළ පැමිණි විද්වතෙකු වූ නිසා", "යුද්ධ පමණක් දිනූ නිසා", "විදේශිකයන් ගෙන්වූ නිසා", "නැව් හැදූ නිසා", "සිංහල, පාලි, සංස්කෘත හා ධර්ම ශාස්ත්‍රයන්හි දැක්වූ අසමසම ප්‍රවීණත්වය නිසා එම ගෞරව නාමය ලැබුණි."),
    q(T, "දඹදෙණි යුගයේ රචිත 'සිදත් සඟරාව' ග්‍රන්ථයේ පරිච්ඡේද හැඳින්වෙන්නේ කුමන නමින්ද?", "සරෝ (වගන්ති / සර)", "පරිච්ඡේද", "අදියර", "කාණ්ඩ", "සිදත් සඟරාවේ අක්ෂර, සන්ධි, සමාස ආදී ව්‍යාකරණ අංග 'සරෝ' නමින් වර්ග කර ඇත."),
    q(T, "යාපහුව බලකොටුවේ ඉහළ මාලයේ දළදා මැදුරේ ජනෙල් නිර්මාණය කර ඇත්තේ කුමන ආකාරයටද?", "විචිත්‍ර කැටයම් සහිත සිදුරු සහිත ගල් දැලිස් ජනෙල් (Stone lattice windows)", "වීදුරු ජනෙල්", "යකඩ දැල්", "ලී ලෑලි", "ගලින්ම නෙළන ලද සිදුරු සහිත දැලිස් ජනෙල් තුළින් ආලෝකය හා සුළඟ මනාව ඇතුළට පැමිණියේය."),
    q(T, "කුරුණෑගල යුගයේදී ලියැවුණු 'සිංහල බෝධිවංශය' ග්‍රන්ථයේ ඇතුළත් ප්‍රධාන ඓතිහාසික විස්තරය කුමක්ද?", "දඹදිව සිට ශ්‍රී මහා බෝධිය ලංකාවට වැඩමවීම සහ බෝධි ආරක්ෂක කුලවල රාජකාරි", "දළදා ඉතිහාසය", "යුද්ධ කතා", "නාවික ගමන්", "බෝධීන් වහන්සේ සමඟ මෙරටට පැමිණි අටළොස් කුලවල ශිල්පීන්ගේ සේවාවන් මෙහි පැහැදිලි කෙරේ."),
    q(T, "ගම්පොළ යුගයේදී සිංහල සාහිත්‍යයට එක්වූ නව කාව්‍ය සම්ප්‍රදාය කුමක්ද?", "සන්දේශ කාව්‍ය සම්ප්‍රදාය (තිසර හා මයුර)", "හටන් කාව්‍ය", "ප්‍රශස්ති කාව්‍ය", "නූතන නිසඳැස්", "කාලිදාසයන්ගේ මේඝදූතය ආභාසයෙන් සිංහල සන්දේශ කාව්‍ය සම්ප්‍රදාය ගම්පොළ යුගයේදී ආරම්භ විය."),
    q(T, "නිරිතදිග රාජධානි කාලයේදී ගම්පොළ හා කුරුණෑගල ප්‍රදේශවල වගා කළ ප්‍රධාන අපනයන බෝගය කුමක්ද?", "කුරුඳු සහ කරාබුනැටි", "තේ", "දුම්කොළ පමණක්", "රබර්", "කඳුකර හා තෙත් බිම්වල වැවුණු කුළුබඩු වර්ග මිලදී ගැනීමට අරාබි හා ආසියානු වෙළෙන්දෝ නිරන්තරයෙන් පැමිණියහ."),
    q(T, "දඹදෙණි යුගයේදී රජවරුන්ගේ දෛනික ආරක්ෂාව සඳහා යොදවා සිටි විශේෂ ආරක්ෂකයන් හැඳින්වූයේ කුමන නමින්ද?", "අතපත්තුවේ සේනාව (රාජකීය අංගාරක්ෂකයන්)", "කුලී හේවායන්", "පොලිසිය", "නාවිකයන්", "රජුගේ ජීවිත ආරක්ෂාව භාරව සිටියේ අතිශය විශ්වාසවන්ත අතපත්තුවේ භටයන්ය."),
    q(T, "නිරිතදිග රාජධානි යුගයේ බිඳවැටීම් හා අගනුවර සංක්‍රමණය වීම පිළිබඳව ඉතිහාසඥයන් දක්වන පොදු නිගමනය කුමක්ද?", "රජරට කේන්ද්‍රීය වියළි කලාපීය ශිෂ්ටාචාරයේ සිට තෙත් කලාපීය වාණිජ ආර්ථිකයකට රට පරිවර්තනය වීම", "ලංකා ඉතිහාසයේ අඳුරු යුගයක් පමණක් වීම", "ජනතාව රට හැර යාම", "කිසිදු සංවර්ධනයක් නොවීම", "දේශපාලන මධ්‍යස්ථාන වෙනස් වුවද සාහිත්‍යය, ආගම හා සංස්කෘතිය තෙත් කලාපය තුළ අඛණ්ඩව සුරක්ෂිත විය."),
    q(T, "දඹදෙණි යුගයේ දෙවන පරාක්‍රමබාහු රජු සිංහල භාෂාවෙන් රචනා කළ 'කව්සිළුමිණ' කාව්‍යයේ අන්තර්ගත කතා පුවත කුමක්ද?", "කුස රජු සහ පභාවතී දේවියගේ ප්‍රේම වෘත්තාන්තය", "රාම රාවණ යුද්ධය", "මහාභාරතය", "විජයාගමනය", "කුස ජාතකය පදනම් කරගනිමින් සංස්කෘත මහා කාව්‍ය ලක්ෂණ උපයෝගී කරගෙන කව්සිළුමිණ රචනා විය."),
    q(T, "දඹදෙණි යුගයේ රචිත 'පූජාවලිය' ග්‍රන්ථය පරිච්ඡේද කීයකින් සමන්විත වේද?", "පරිච්ඡේද තිස් හතරකින් (34)", "පරිච්ඡේද දහයකින්", "පරිච්ඡේද පනහකින්", "පරිච්ඡේද සියයකින්", "පූජාවලියේ අවසාන පරිච්ඡේදය ශ්‍රී ලංකාවේ රාජාවලිය විස්තර කරන අගනා ඓතිහාසික මූලාශ්‍රයකි."),
    q(T, "දඹදෙණි යුගයේදී සංඝ සංශෝධනයක් කරමින් 'දඹදෙණි කතිකාවත' පිහිටුවීමට මූලික වූ සංඝ නායක හිමිනම කවුද?", "දිඹුලාගල ආරණ්‍යවාසී මේධංකර මහා ස්ථවිරයන් වහන්සේ", "මහානාම හිමි", "බුද්ධඝෝෂ හිමි", "සාරිපුත්ත හිමි", "රජුගේ අනුග්‍රහයෙන් සංඝරත්නය එක්රැස් කර භික්ෂු විනය ප්‍රතිසංස්කරණය කළහ."),
    q(T, "දඹදෙණි යුගයේදී සාහිත්‍ය නිර්මාණ බිහි කිරීමට රජුට අමතරව දායක වූ ප්‍රධාන පැවිදි පඬිවරුන් කවුද?", "ධර්මසේන හිමි, බුද්ධපුත්‍ර හිමි හා වේදේහ හිමි", "මහානාම හිමි පමණක්", "ශ්‍රී රාහුල හිමි පමණක්", "මිහිඳු හිමි", "සද්ධර්මරත්නාවලිය, පූජාවලිය, සමන්තකූට වණ්ණනාව ආදී අගනා කෘති මේ යුගයේ බිහිවිය."),
    q(T, "යාපහුව පර්වත බලකොටුවේ ඉහළ ප්‍රාකාරයේ ආරක්ෂාව වෙනුවෙන් තනා තිබූ මුර අට්ටාලවල කාර්යය කුමක්ද?", "දුනුවායන් යොදවා සතුරු ප්‍රහාර ව්‍යර්ථ කිරීම සහ ආක්‍රමණ නිරීක්ෂණය කිරීම", "ධාන්‍ය ගබඩා කිරීම පමණක්", "නැටුම් පැවැත්වීම", "වෙළෙඳාම් කිරීම", "පර්වතය වටා බෑවුමෙන් නැග එන සතුරන්ට පහසුවෙන් ඊතල හා ගල් ප්‍රහාර එල්ල කිරීමට මුර අට්ටාල සකසා තිබුණි."),
    q(T, "යාපහුව රාජධානිය ක්‍රියාත්මක වූ කෙටි කාලය තුළ ලංකාවේ මුහුදු වෙළෙඳාම වර්ධනය වීමට හේතුව කුමක්ද?", "යාපහුව බටහිර සහ වයඹදිග මුහුදු තොටුපළවලට සමීපව පිහිටා තිබීම", "මුහුද පර්වතය අසලටම පැමිණීම", "විදේශිකයන් සියල්ල යටත් වීම", "රජු නැව් සෑදීම පමණක් කිරීම", "මාන්තොට, හලාවත හා පුත්තලම වැනි වරායන් මගින් අන්තර්ජාතික වෙළෙඳ මාර්ග පාලනය කළ හැකි විය."),
    q(T, "කුරුණෑගල යුගයේ රජකළ හතරවන පරාක්‍රමබාහු රජු ඉදි කළ ප්‍රකට ආරණ්‍ය සේනාසනයක් වන්නේ කුමක්ද?", "අස්ගිරි විහාරය (මුල් අවධිය)", "මල්වතු විහාරය", "රුවන්වැලිසෑය", "ථූපාරාමය", "කුරුණෑගල සමයේ ආරම්භ වූ ආගමික මධ්‍යස්ථාන පසුව මහනුවර යුගයේ සංඝ සභාවන්ට පදනම විය."),
    q(T, "කුරුණෑගල යුගයේ රචිත 'අනාගතවංශය' කෘතියෙන් විස්තර කෙරෙන්නේ කුමක් පිළිබඳවද?", "මතු බුදුවන මෛත්‍රී බුදුරජාණන් වහන්සේගේ පහළවීම හා ශාසන ඉතිහාසය", "පසුගිය යුද්ධ", "රජවරුන්ගේ ළමා කාලය", "කෘෂිකාර්මික නීති", "විලාගමුව තෙරුන් විසින් අනාගත බුදුවරුන් පිළිබඳ විශ්වාසය විස්තර කරමින් මෙය රචනා කරන ලදී."),
    q(T, "ගම්පොළ යුගයේදී 'ඇම්බැක්කේ දේවාලයේ' දිග්ගෙයි දැව කුළුණු සංඛ්‍යාව කීයද?", "කැටයම් සහිත දැව කුළුණු තිස් දෙකකි (32)", "කුළුණු හතරකි", "කුළුණු දහයකි", "කුළුණු පනහකි", "මෙම කුළුණු මත විවිධාකාර ජනප්‍රවාද, මෝස්තර හා සත්ත්ව රූප ඉතා සියුම්ව කැටයම් කර ඇත."),
    q(T, "ඇම්බැක්කේ දැව කැටයම් අතර හමුවන 'හංස පූට්ටුව' සංකේතවත් කරන්නේ කුමක්ද?", "සෞභාග්‍යය, එකමුතුකම සහ අලංකාරය", "යුද්ධය", "සාගතය", "බිය", "හංසයන් දෙදෙනෙකුගේ ගෙල එකට පැටලී ඇති ආකාරය දැක්වෙන හංස පූට්ටුව සාම්ප්‍රදායික මංගල මෝස්තරයකි."),
    q(T, "ගම්පොළ යුගයේදී ඉදිකළ 'ලංකාතිලක විහාරයේ' දැකගත හැකි වාස්තු විද්‍යාත්මක ශෛලිය කුමක්ද?", "සිංහල සම්ප්‍රදාය සහ දකුණු ඉන්දියානු ද්‍රවිඩ සම්ප්‍රදායේ මනා සංකලනයක්", "පිරිසිදු රෝම ශෛලිය", "ගොතික් ශෛලිය", "චීන පැගෝඩා ශෛලිය", "ගඩොල් බිත්ති, ආරුක්කු සහ පිටත දේවාල කුටි තුළින් බහුසංස්කෘතික ගෘහ නිර්මාණ ලක්ෂණ පෙන්වයි."),
    q(T, "ගම්පොළ යුගයේ විදේශීය වෙළෙඳුන් ලංකාවෙන් රැගෙන ගිය ප්‍රධාන වනජ සම්පත කුමක්ද?", "කළුවර, සඳුන් සහ තේක්ක දැව", "රබර්", "තේ", "කඩදාසි", "අරාබි හා ඉන්දීය නැව් තැනීමට හා සුඛෝපභෝගී භාණ්ඩ සඳහා මෙරට වටිනා දැව මිලදී ගත්හ."),
    q(T, "යාපනය රාජධානියේ මුතු කිමිදීමේ කර්මාන්තය පාලනය වූයේ කුමන ප්‍රදේශය කේන්ද්‍ර කරගෙනද?", "මන්නාරම සහ සිලාවතුර මුතු වෙරළ", "හම්බන්තොට", "ත්‍රිකුණාමලය", "පානදුර", "මන්නාරම් බොක්කේ මුතු කිමිදීමේ තොටුපළවල් අන්තර්ජාතික වෙළෙඳාමේ ඉතා ප්‍රකට විය."),
    q(T, "යාපනය අර්ධද්වීපයේ ගොවිතැන් කටයුතු සඳහා භාවිත කළ සාම්ප්‍රදායික ජල එසවීමේ ක්‍රමය කුමක්ද?", "තුලා ළිං ක්‍රමය (Well-sweep / Thula)", "විශාල වැව් ඇළ මාර්ග", "ගංවතුර ජලය", "හිම ජලය", "භූගත කරදිය නොවන මිරිදිය ළිංවලින් ලී දණ්ඩක් ආධාරයෙන් ජලය ඇද ගොවිතැන් කළහ."),
    q(T, "දඹදෙණි යුගයේ රචිත 'සරස්වතී නිඝණ්ඩුව' කුමන විෂය ක්ෂේත්‍රයකට අයත් ග්‍රන්ථයක්ද?", "ආයුර්වේද වෛද්‍ය විද්‍යාව (ඖෂධ ශබ්දකෝෂයක්)", "යුද විද්‍යාව", "නාවික විද්‍යාව", "නැටුම් කලාව", "ඖෂධ පැළෑටි හා ගුණාංග විස්තර කරන වෛද්‍ය විද්‍යාත්මක ග්‍රන්ථයකි."),
    q(T, "දඹදෙණි යුගයේදී දළදා වහන්සේ උදෙසා 'දළදා පෙරහැර' අඛණ්ඩව පැවැත්වීම මගින් තහවුරු කළේ කුමක්ද?", "බෞද්ධ රාජ්‍යත්වයේ අභිමානය සහ ජනතාවගේ ආගමික ප්‍රබෝධය", "යුද්ධයට සූදානම් වීම පමණක්", "විදේශිකයන් බිය ගැන්වීම", "මුදල් එකතු කිරීම", "රාජධානිය අර්බුද මැද වුවද සංස්කෘතික හා ආගමික උරුමය අඛණ්ඩව පවත්වාගෙන යාමට රජවරු කැපවූහ."),
    q(T, "යාපහුව නගරයේ නටබුන් අතර ඇති 'රාජ සභා මණ්ඩපය' පිහිටා ඇත්තේ කොතැනද?", "පියගැට පෙළ මුදුනේ පිහිටි දළදා මැදුර අසල", "පර්වතය පාමුල දිය අගල තුළ", "පිටත වනාන්තරයේ", "නගර දොරටුව අසල", "කළුගල් කුළුණු මත පිහිටි විචිත්‍ර මණ්ඩපයක් ලෙස මෙය තනා තිබුණි."),
    q(T, "කුරුණෑගල යුගයේදී රජකළ හතරවන පරාක්‍රමබාහු රජු බුද්ධ ප්‍රතිමාවලට කළ සත්කාරයක් ලෙස වංශකතාවල දැක්වෙන්නේ කුමක්ද?", "රනින්, රිදියෙන් පිළිම තනවා මැණික් ඔබ්බවා පුද පූජා පැවැත්වීම", "සියලු පිළිම විනාශ කිරීම", "පිළිම විදේශයන්ට විකිණීම", "පූජා නැවැත්වීම", "දළදා මැදුර ඇතුළු වෙහෙර විහාර රන් රිදී ආලේප කර අලංකාර කළේය."),
    q(T, "ගම්පොළ යුගයේදී රචනා වූ 'එළු අත්තනගලු වංශය' කෘතියේ අන්තර්ගතය කුමක්ද?", "පාලි හත්ථවනගල්ල විහාර වංශයේ සිංහල අනුවාදය", "යාපහුවේ ඉතිහාසය", "කෝට්ටේ යුද්ධ", "සීතාවක සටන්", "සිරිසඟබෝ රජුගේ උදාර චරිතය හා අත්තනගල්ලේ ඉතිහාසය සිංහලෙන් ඉදිරිපත් කළේය."),
    q(T, "ගම්පොළ යුගයේදී කෝට්ටේ බලකොටුව තැනූ අලගක්කෝනාර අමාත්‍යවරයාගේ මූලස්ථානය පිහිටියේ කොහේද?", "රයිගම (බණ්ඩාරගම අසල)", "කෑගල්ල", "මාතලේ", "යාපනය", "රයිගම කේන්ද්‍ර කරගත් අලකේශ්වර පරපුර බස්නාහිර මුහුදුබඩ ප්‍රදේශයේ ආරක්ෂාව තහවුරු කළහ."),
    q(T, "ආර්යචක්‍රවර්තී රජවරුන්ගේ පාලන කාලයේදී යාපනයේ කෘෂිකර්මාන්තයට වඩා ප්‍රමුඛ වූයේ කුමන ආර්ථික අංශයද?", "මුහුදු වෙළෙඳාම සහ තීරුබදු ආදායම", "තේ වගාව", "කුඹුරු ගොවිතැන පමණක්", "පතල් කැණීම", "නැව් තොටුපළවල් ආශ්‍රිතව වෙළෙඳ නැව්වලින් අය කළ තීරුබදු යාපනය රාජධානියේ ප්‍රධාන ආදායම විය."),
    q(T, "නිරිතදිග රාජධානි යුගයේදී සමාජයේ කුල ක්‍රමය ක්‍රියාත්මක වූයේ කුමන අරමුණක් සඳහාද?", "වෘත්තීය ශ්‍රම බෙදීම සහ රාජකාරි ක්‍රමය පවත්වාගෙන යාම සඳහා", "ජනයා සමානව තැබීමට", "යුද්ධ නැවැත්වීමට", "විදේශිකයන් පාලනයට", "එක් එක් කුලයට අයත් සාම්ප්‍රදායික වෘත්තීන් මගින් රාජ්‍ය සේවය හා විහාර සේවය සැපයිණි."),
    q(T, "දඹදෙණි යුගයේදී ගම්බද ජනතාවගේ ප්‍රධාන ආහාර බෝගය වූයේ කුමක්ද?", "බත් (සහල්) සහ කුරක්කන්", "තිරිඟු පාන්", "අල වර්ග පමණක්", "පලතුරු පමණක්", "කුඹුරුවලින් ලැබුණු වී හා හේන්වලින් ලැබුණු කුරක්කන්, මෙනේරි ප්‍රධාන ආහාරය විය."),
    q(T, "යාපහුව පර්වත මුදුනෙන් හමුවන සුවිශේෂී ජල කළමනාකරණ අංගය කුමක්ද?", "ස්වාභාවික ගල් කුහර උපයෝගී කරගෙන තැනූ වැසි ජලය රැස්වන පොකුණු", "භූගත නළ පද්ධති පමණක්", "විශාල ගංගා", "ජල මෝටර්", "පර්වත මුදුනේ වාසය කළ රජුට හා සෙබළුන්ට ජලය ලබා ගැනීමට ස්වාභාවික ගල් පොකුණු ප්‍රයෝජනවත් විය."),
    q(T, "කුරුණෑගල යුගයේදී 'ඇතුගල' පාමුල ඉදිකළ දළදා මාලිගයේ අද ඉතිරිව ඇති නටබුන් මොනවාද?", "ගල් කුළුණු පාදම් සහ සඳකඩපහණ කොටස්", "සම්පූර්ණ මාලිගයම", "කිසිවක් නැත", "වීදුරු කුළුණු", "කුරුණෑගල නගර මධ්‍යයේ පුරාණ දළදා මැදුරේ ශෛලමය නටබුන් අදටත් දැකගත හැකිය."),
    q(T, "ගම්පොළ යුගයේදී අලගක්කෝනාර අමාත්‍යවරයා ආරම්භ කළ කෝට්ටේ බලකොටුව හැඳින්වූ මුල් නම කුමක්ද?", "ජයවර්ධනපුර කෝට්ටේ", "අනුරාධපුරය", "සීගිරිය", "විජිතපුර", "සතුරන් ජය ගෙන සෞභාග්‍යය වර්ධනය කරන නගරය යන අරුතින් 'ජයවර්ධනපුර' නමින් නම් කෙරිණි."),
    q(T, "චීන සෙන්පති චෙං හෝ විසින් පිහිටුවන ලද 'ගාලු ත්‍රෛභාෂික සෙල්ලිපිය' සොයාගත්තේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 1911 දී එච්. එෆ්. ටොම්ලින් මහතා විසින්", "ක්‍රි.ව. 1815 දී", "ක්‍රි.ව. 1505 දී", "ක්‍රි.ව. 2000 දී", "ගාල්ල නගරයේ කාණුවක් මතින් හමුවූ මෙම අගනා ශිලා ලේඛනය ජාතික උරුමයක් ලෙස සුරක්ෂිත කර ඇත."),
    q(T, "යාපනය රාජධානිය ක්‍රි.ව. 1619 දී අවසන් වරට යටත් කරගත් විදේශීය ජාතිය කවුද?", "පෘතුගීසීන් (පිලිප් ද ඔලිවේරා යටතේ)", "ලන්දේසීන්", "ඉංග්‍රීසීන්", "ප්‍රංශ ජාතිකයන්", "සන්ගිලි කුමරු පරාජය කර පෘතුගීසීන් යාපනය රාජධානිය මුළුමනින්ම අත්පත් කරගත්තේය."),
    q(T, "නිරිතදිග රාජධානි යුගයේ විදේශ වෙළෙඳාමේදී වඩාත් ප්‍රයෝජනවත් වූ ලාංකික සත්ත්ව සම්පත කුමක්ද?", "යුද අභ්‍යාස සඳහා පුහුණු කළ අලි ඇතුන්", "අශ්වයන්", "ඔටුවන්", "ගවයන්", "ඉන්දියාවේ හා මැදපෙරදිග රජවරුන් මෙරට ඇතුන් මිලදී ගැනීමට විශාල ධනයක් වැය කළහ."),
    q(T, "දඹදෙණි යුගයේ දෙවන පරාක්‍රමබාහු රජු විසින් කරවන ලද 'සිරිලක්විජය' මහා පූජාව පැවැත්වූයේ කුමන ස්ථානයේදීද?", "දඹදෙණියේ විජයසුන්දරාරාමයේදී", "කැළණියේදී", "අනුරාධපුරයේදී", "දෙවුන්දරදී", "ලංකාව එක්සේසත් කිරීම හා සතුරු ආක්‍රමණ පරාජය කිරීම සැමරීමට මෙම මහා පූජාව පැවැත්වීය."),
    q(T, "යාපහුව බලකොටුවේ ආරක්ෂාව තහවුරු කිරීමට යොදාගත් බාහිර ප්‍රාකාරයේ උස ආසන්න වශයෙන් කොපමණද?", "අඩි 12කට වඩා උස් වූ ගල් හා මැටි බැම්මකි", "අඩි දෙකකි", "අඩි පනහකි", "අඩි සියයකි", "සතුරන්ට ක්ෂණිකව කඩා වැදිය නොහැකි ලෙස පුළුල් දිය අගලක් සමඟ මෙම ප්‍රාකාරය තනා තිබුණි."),
    q(T, "කුරුණෑගල යුගයේ බිහිවූ 'පන්සිය පනස් ජාතක පොත' සිංහල සංස්කෘතියට කළ ප්‍රධානතම බලපෑම කුමක්ද?", "සිංහල ගැමි සමාජයේ සදාචාරය, ආචාරධර්ම හා භාෂා ඥානය පෝෂණය කිරීම", "යුදකාමී සමාජයක් බිහි කිරීම", "විදේශ භාෂා ප්‍රචලිත කිරීම", "සම්ප්‍රදායන් විනාශ කිරීම", "ජාතක කතා ඇසුරෙන් පන්සල කේන්ද්‍ර කරගත් උසස් සදාචාර සම්පන්න සමාජයක් ගොඩනැගුණි."),
    q(T, "ගම්පොළ යුගයේදී දැකගත හැකි 'මැදවල විහාරයේ' ඇති ඓතිහාසික ලක්ෂණය කුමක්ද?", "ටැම්පිට විහාර සම්ප්‍රදාය සහ තුන්වන වික්‍රමබාහුගේ සෙල්ලිපිය", "ගෙඩිගේ සම්ප්‍රදාය", "ගල් ලෙන් පමණක් වීම", "ස්තූපයක් පමණක් වීම", "ගල් කුළුණු මත දැවයෙන් තැනූ ටැම්පිට විහාර වාස්තු විද්‍යාව මෙහි විශේෂත්වයකි."),
    q(T, "ගම්පොළ යුගයේදී රාජකීය අනුග්‍රහය ලැබූ සතර මහා දේවාල අතරට අයත් නොවන්නේ කුමක්ද?", "පල්ලිය", "උපුල්වන් දේවාලය", "සමන් දේවාලය", "විභීෂණ දේවාලය", "බෞද්ධ ආරක්ෂක දෙවිවරුන් ලෙස සලකා සතර මහා දේවාල නඩත්තු කිරීමට රජවරු පියවර ගත්හ."),
    q(T, "යාපනය රාජධානියේ ආර්යචක්‍රවර්තී රජවරුන් හා දකුණු ඉන්දියාවේ විජයනගර් අධිරාජ්‍යය අතර පැවති සබඳතාව කුමක්ද?", "මිත්‍රශීලී වෙළෙඳ සබඳතා හා විටින් විට කප්පම් ගෙවීම", "නිරන්තර යුද්ධ පැවතීම පමණක්", "කිසිදු සබඳතාවක් නොතිබීම", "විජයනගරය යාපනයට යටත්ව තිබීම", "විජයනගර් අධිරාජ්‍යයේ බලපෑම හමුවේ යාපනය රජවරු කප්පම් ගෙවමින් තම ස්වාධීනත්වය රැක ගත්හ."),
    q(T, "නිරිතදිග රාජධානි කාලයේදී ලංකාවට පැමිණි සුප්‍රකට දේශාටක ඉබන් බතූතා ලංකාවේ සංචාරය කළේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 1344 දී", "ක්‍රි.ව. 1505 දී", "ක්‍රි.ව. 1215 දී", "ක්‍රි.ව. 1017 දී", "ගම්පොළ යුගයේදී ලංකාවට පැමිණි ඉබන් බතූතා යාපනය, පුත්තලම, ගම්පොළ හා ශ්‍රී පාදය වැඳපුදා ගත්තේය."),
    q(T, "ඉබන් බතූතා සිය චාරිකා සටහන්වල යාපනයේ ආර්යචක්‍රවර්තී රජු ගැන සඳහන් කළ විශේෂත්වය කුමක්ද?", "මුතු කිමිදීමේ ඒකාධිකාරය හිමි, විශාල නැව් හිමි ධනවත් රජෙකු බව", "දුප්පත් පාලකයෙකු බව", "වෙළෙඳාමට අකමැති බව", "භික්ෂුවක් බව", "ආර්යචක්‍රවර්තී රජු සතුව පැවති මුහුදු බලය හා මුතු වෙළෙඳාම ඉබන් බතූතා පැසසුමට ලක් කළේය."),
    q(T, "දඹදෙණි යුගයේදී 'විජයසුන්දරාරාමය' පිහිටුවන ලද්දේ දඹදෙණි පර්වතයේ කුමන දිශාවේද?", "පර්වතය පාමුල නගර මධ්‍යයේ", "පර්වත මුදුනේ", "ගං පතුලේ", "වනාන්තරයේ", "දඹදෙණිය රජ මාලිගයට නුදුරින් පිහිටි විජයසුන්දරාරාමය ප්‍රධාන ආගමික මධ්‍යස්ථානය විය."),
    q(T, "යාපහුව පර්වත මුදුනෙන් හමුවන සෙල්ලිපි අයත් වන්නේ කුමන ඓතිහාසික යුගවලටද?", "මුල් බ්‍රාහ්මී අවධියේ සිට 13 වන සියවස දක්වා විවිධ අවධිවලට", "පෘතුගීසි යුගයට පමණක්", "ලන්දේසි යුගයට පමණක්", "නූතන යුගයට", "අනුරාධපුර යුගයේ සිටම සංඝරත්නය වාසය කළ ලෙන් ආරාමයක් ලෙස පැවති බව සෙල්ලිපිවලින් හෙළි වේ."),
    q(T, "කුරුණෑගල රාජධානියෙන් පසුව ගම්පොළට අගනුවර මාරු වීමට හේතු වූ දේශගුණික හෝ භූගෝලීය වාසිය කුමක්ද?", "කඳුකර භූමිය ස්වාභාවිකවම විදේශීය ආක්‍රමණවලින් වඩාත් ආරක්ෂිත වීම", "මුහුදු වෙරළට ළඟා වීමට පහසු වීම", "හිම ක්‍රීඩා කිරීමට හැකිවීම", "වැසි නොවැටීම", "මධ්‍යම කඳුකරයේ දුෂ්කර මාවත් ආක්‍රමණික හමුදාවන්ට තරණය කිරීමට නොහැකි තරම් බාධක සහිත විය."),
    q(T, "ගම්පොළ යුගයේදී ඉදිකළ 'ගඩලාදෙණිය විහාරයේ' වහල මත ඉදිකර ඇති සුවිශේෂී අංගය කුමක්ද?", "කුඩා ශෛලමය ස්තූපයක් (ශිඛරයක්)", "ලී කුළුණක්", "වීදුරු ගෝලයක්", "යකඩ කුළුණක්", "විහාර ගොඩනැගිල්ලේ මුදුනේ ගලින්ම නිමවූ ස්තූපයක් පිහිටුවා තිබීම දකුණු ඉන්දියානු ශිඛර සම්ප්‍රදායට සමානය."),
    q(T, "නිරිතදිග රාජධානි කාලයේදී ගම්බද ජනතාව අතර බහුලව භාවිත වූ කුළුබඩු වර්ගයක් නොවන්නේ කුමක්ද?", "ඇපල්", "කුරුඳු", "ගම්මිරිස්", "කරාබුනැටි", "ඇපල් මෙරට වැවුණු බෝගයක් නොවන අතර කුළුබඩු වර්ග බහුලව වගා කර අපනයනය කළහ."),
    q(T, "දඹදෙණි යුගයේ රචිත 'සද්ධර්මරත්නාවලිය' කෘතියේ අරමුණ කුමක් ලෙස කතුවරයා දක්වයිද?", "ධර්මය නොදත් අඥානයන්ට ධර්මය පහදා දී සිත් පහදවා ලීම", "රජුට ප්‍රශස්ති කීම", "මුදල් ඉපැයීම", "යුද්ධයට පෙළඹවීම", "ධර්මසේන හිමියන් සරල ගැමි උපමා භාවිත කරමින් ගැමි ජනතාව සදාචාර සම්පන්න කිරීමට උත්සාහ කළහ."),
    q(T, "යාපහුවේ පියගැට පෙළ මුදුනේ පිහිටි දොරටුවේ දෙපස කැටයම් කර ඇති මිථ්‍යා සත්ත්ව රූපය කුමක්ද?", "මකර රූප හා වාමන රූප", "සිංහ රූප පමණක්", "ඇත් රූප පමණක්", "මොණර රූප", "මකර තොරණ හා වාමන රූප තුළින් ප්‍රවේශ දොරටුව අලංකාරවත් කර ඇත."),
    q(T, "කුරුණෑගල යුගයේ රජකළ හතරවන පරාක්‍රමබාහු රජුගේ කාලයේ රටේ පැවති සාමකාමී වාතාවරණය නිසා සිදුවූයේ කුමක්ද?", "සාහිත්‍යය, ධර්ම ශාස්ත්‍රය හා ආගමික පුනර්ජීවනය ඉහළින්ම මල්ඵල ගැන්වීම", "රට බෙදී යාම", "ආර්ථිකය විනාශ වීම", "ජනතාව රට හැර යාම", "අභ්‍යන්තර යුද්ධ නොපැවති බැවින් ශාස්ත්‍රීය හා බෞද්ධ පුනරුදයක් ඇතිවිය."),
    q(T, "ගම්පොළ යුගයේදී රචනා වූ 'මයුර සන්දේශය' කාව්‍යයේ කතුවරයා කවුදැයි සැලකෙන්නේද?", "කවීශ්වර පණ්ඩිතයන්", "ශ්‍රී රාහුල හිමි", "වීදාගම මෛත්‍රිය හිමි", "ගුරුළුගෝමී", "තුන්වන වික්‍රමබාහු රජ සමයේ කවීශ්වර විසින් මයුර සන්දේශය රචනා කරන ලදී."),
    q(T, "යාපනය රාජධානිය ක්‍රි.ව. 15 වන සියවසේදී කෝට්ටේ හයවන පරාක්‍රමබාහු රජුට යටත් වූ බව තහවුරු කරන ප්‍රධාන සිංහල සාහිත්‍ය මූලාශ්‍රය කුමක්ද?", "කෝකිල සන්දේශය සහ සැළලිහිණි සන්දේශය", "මහාවංශය පමණක්", "දීපවංශය", "චූලවංශය", "සපුමල් කුමරු යාපනය ජයගෙන නල්ලූර්හි පාලනය ගෙන ගිය ආකාරය කෝකිල සන්දේශයේ විස්තර කෙරේ."),
    q(T, "නිරිතදිග රාජධානි යුගයේ අවසානය සනිටුහන් කරමින් ශ්‍රී ලංකාව යළිත් තනි පාලනයක් යටතට එක්සේසත් කළ ශ්‍රේෂ්ඨ රජු කවුද?", "හයවන පරාක්‍රමබාහු රජු (කෝට්ටේ)", "දෙවන පරාක්‍රමබාහු", "හතරවන විජයබාහු", "පළමුවන බුවනෙකබාහු", "ක්‍රි.ව. 1412-1467 කාලයේ කෝට්ටේ රජකළ හයවන පරාක්‍රමබාහු රජු මුළු ලංකාවම එක්සේසත් කළ අවසාන සිංහල රජුය.")
  )
}
